use super::*;
use crate::metrics::DedupPutStageTimings;
use std::sync::atomic::Ordering;

#[derive(Clone, Copy, Debug)]
struct RcApplyAction {
    op_idx: usize,
    pba: Pba,
    delta: i64,
    standalone_refcount: bool,
    remap_freed_candidate: bool,
    /// True when this action is generated by an `L2pRemapRange` apply
    /// rather than a per-LBA `L2pRemap`. The post-apply refcount
    /// merger pushes freed pbas into `L2pRemapRange.freed_pbas: Vec`
    /// when set, vs. assigning `L2pRemap.freed_pba: Option<Pba>` when
    /// clear.
    range_op: bool,
}

/// One unit of work in an L2P shard's bucket. The pre-existing path
/// stored only op indices and the apply re-inspected each op; with the
/// addition of [`WalOp::L2pRemapRange`] a single op can target many
/// LBAs that map to different L2P shards, so the bucket plan needs to
/// carry per-shard slice info as well.
#[derive(Clone, Debug)]
pub(super) enum L2pBucketEntry {
    /// Per-LBA op (`L2pPut`, `L2pDelete`, or `L2pRemap`). Apply looks
    /// up `ops[op_idx]` and dispatches by variant.
    Single(usize),
    /// One L2P shard's slice of a `WalOp::L2pRemapRange`. `lba_offsets`
    /// indexes into the op's `values` slice. A range op crossing 2
    /// shards produces two `RangeSlice` entries (one per shard) sharing
    /// the same `op_idx`; the outcome merger combines their partial
    /// `L2pRemapRange` results.
    RangeSlice {
        op_idx: usize,
        lba_offsets: Box<[u32]>,
    },
}

impl L2pBucketEntry {
    fn op_idx(&self) -> usize {
        match self {
            L2pBucketEntry::Single(idx) => *idx,
            L2pBucketEntry::RangeSlice { op_idx, .. } => *op_idx,
        }
    }
}

struct L2pBucketApplyResult {
    outcomes: Vec<(usize, ApplyOutcome)>,
    rc_actions: Vec<RcApplyAction>,
}

#[derive(Default)]
struct RcBucketApplyResult {
    refcount_outcomes: Vec<(usize, u32)>,
    /// `(op_idx, pba, range_op)` — `range_op = true` means the freed
    /// pba should be appended to the op's `L2pRemapRange.freed_pbas`
    /// Vec; `false` means it sets `L2pRemap.freed_pba: Option<Pba>`.
    remap_freed: Vec<(usize, Pba, bool)>,
}

/// Land an L2P bucket's per-op outcome into the `outcomes` vec. For
/// `L2pRemapRange` outcomes that may have been split across multiple
/// shard lanes, merge with any partial outcome already at the slot:
/// per-LBA `applied` bits are OR-ed, `prevs` slots are filled in where
/// previously `None`, and `freed_pbas` are concatenated. All other
/// outcomes are 1-shard-per-op and simply overwrite.
fn merge_l2p_outcome(
    outcomes: &mut [Option<ApplyOutcome>],
    idx: usize,
    incoming: ApplyOutcome,
) {
    match incoming {
        ApplyOutcome::L2pRemapRange {
            applied: in_applied,
            prevs: in_prevs,
            freed_pbas: in_freed,
        } => match outcomes[idx].take() {
            None => {
                outcomes[idx] = Some(ApplyOutcome::L2pRemapRange {
                    applied: in_applied,
                    prevs: in_prevs,
                    freed_pbas: in_freed,
                });
            }
            Some(ApplyOutcome::L2pRemapRange {
                applied: mut existing_applied,
                prevs: existing_prevs,
                mut freed_pbas,
            }) => {
                debug_assert_eq!(existing_applied.len(), in_applied.len());
                debug_assert_eq!(existing_prevs.len(), in_prevs.len());
                let mut merged_prevs = existing_prevs.into_vec();
                let in_prevs_vec = in_prevs.into_vec();
                for (i, slot) in merged_prevs.iter_mut().enumerate() {
                    if in_applied[i] {
                        existing_applied[i] = true;
                    }
                    if slot.is_none() && in_prevs_vec[i].is_some() {
                        *slot = in_prevs_vec[i];
                    }
                }
                freed_pbas.extend(in_freed);
                outcomes[idx] = Some(ApplyOutcome::L2pRemapRange {
                    applied: existing_applied,
                    prevs: merged_prevs.into_boxed_slice(),
                    freed_pbas,
                });
            }
            Some(other) => {
                panic!(
                    "L2pRemapRange partial at idx={idx} but existing outcome is {other:?}"
                );
            }
        },
        other => {
            outcomes[idx] = Some(other);
        }
    }
}

struct LaneDispatchPlan {
    l2p_sorted: Vec<((VolumeOrdinal, usize), Vec<L2pBucketEntry>)>,
    rc_buckets: Vec<Vec<RcApplyAction>>,
    rc_enqueued: Vec<bool>,
    /// Dedup op indices grouped by shard. Outer length always equals
    /// `Db::dedup_lanes.len()`; an empty inner vec means that shard
    /// has no work in this commit and gets no `DispatchLaneKey::Dedup`
    /// footprint entry.
    dedup_buckets: Vec<Vec<usize>>,
}

struct QueuedLanePlan {
    ops: Arc<Vec<WalOp>>,
    l2p_receivers: Vec<crossbeam_channel::Receiver<Result<L2pBucketApplyResult>>>,
    rc_buckets: Vec<Vec<RcApplyAction>>,
    /// Per-shard dedup op indices. Drained into the per-shard apply
    /// closures during `apply_ops_laned`.
    dedup_buckets: Vec<Vec<usize>>,
    /// One pending slot per non-empty bucket (entries for empty
    /// buckets are `None`).
    dedup_pendings: Vec<Option<PendingApplyWork>>,
}

#[derive(Clone, Copy, Debug, Default)]
struct LanedApplyTiming {
    l2p_wait: std::time::Duration,
    rc_enqueue: std::time::Duration,
    rc_wait: std::time::Duration,
    dedup_enqueue: std::time::Duration,
    dedup_wait: std::time::Duration,
}

#[derive(Clone, Copy, Debug, Default)]
struct CommitTiming {
    drop_gate_wait: std::time::Duration,
    plan: std::time::Duration,
    encode: std::time::Duration,
    wal_submit: std::time::Duration,
    dispatch_wait: std::time::Duration,
    apply_gate_wait: std::time::Duration,
    lane_enqueue: std::time::Duration,
    apply: std::time::Duration,
    laned: LanedApplyTiming,
    finish_global_wait: std::time::Duration,
}

struct CommitApplyContext<'a> {
    commit_started: std::time::Instant,
    cpu_started: Option<std::time::Duration>,
    timing: CommitTiming,
    volumes: HashMap<VolumeOrdinal, Arc<Volume>>,
    serial_apply: bool,
    plan: Option<LaneDispatchPlan>,
    plan_l2p_lanes: usize,
    plan_rc_lanes: usize,
    plan_dedup_ops: usize,
    dispatch_lanes: usize,
    ops: &'a [WalOp],
}

struct ActiveApplyGuard<'a> {
    db: &'a Db,
    lsn: Lsn,
}

impl Drop for ActiveApplyGuard<'_> {
    fn drop(&mut self) {
        self.db.active_apply_lsns.lock().remove(&self.lsn);
    }
}

impl DispatchFootprint {
    pub(super) fn global() -> Self {
        Self {
            global: true,
            lanes: BTreeSet::new(),
        }
    }

    fn from_lane_plan(plan: &LaneDispatchPlan) -> Self {
        let mut lanes = BTreeSet::new();
        for ((vol_ord, sid), _) in &plan.l2p_sorted {
            lanes.insert(DispatchLaneKey::L2p(*vol_ord, *sid));
        }
        for (sid, enqueued) in plan.rc_enqueued.iter().copied().enumerate() {
            if enqueued {
                lanes.insert(DispatchLaneKey::Refcount(sid));
            }
        }
        for (sid, bucket) in plan.dedup_buckets.iter().enumerate() {
            if !bucket.is_empty() {
                lanes.insert(DispatchLaneKey::Dedup(sid as u32));
            }
        }
        Self {
            global: false,
            lanes,
        }
    }

    fn conflicts(&self, other: &Self) -> bool {
        self.global || other.global || self.lanes.iter().any(|lane| other.lanes.contains(lane))
    }
}

fn wal_lane_key(op: &WalOp) -> u64 {
    match op {
        WalOp::L2pPut { vol_ord, lba, .. }
        | WalOp::L2pDelete { vol_ord, lba }
        | WalOp::L2pRemap { vol_ord, lba, .. } => {
            let mut bytes = [0u8; 10];
            bytes[..2].copy_from_slice(&vol_ord.to_be_bytes());
            bytes[2..].copy_from_slice(&lba.to_be_bytes());
            xxh3_64(&bytes)
        }
        WalOp::L2pRangeDelete { vol_ord, start, .. } => {
            let mut bytes = [0u8; 10];
            bytes[..2].copy_from_slice(&vol_ord.to_be_bytes());
            bytes[2..].copy_from_slice(&start.to_be_bytes());
            xxh3_64(&bytes)
        }
        WalOp::L2pRemapRange {
            vol_ord, start_lba, ..
        } => {
            let mut bytes = [0u8; 10];
            bytes[..2].copy_from_slice(&vol_ord.to_be_bytes());
            bytes[2..].copy_from_slice(&start_lba.to_be_bytes());
            xxh3_64(&bytes)
        }
        WalOp::DedupPut { hash, .. }
        | WalOp::DedupPutGuarded { hash, .. }
        | WalOp::DedupDelete { hash, .. }
        | WalOp::DedupCompareDelete { hash, .. }
        | WalOp::DedupComparePut { hash, .. } => xxh3_64(hash),
        WalOp::DropSnapshot { id, .. } => xxh3_64(&id.to_be_bytes()),
        WalOp::CreateVolume { ord, .. } | WalOp::DropVolume { ord, .. } => {
            xxh3_64(&ord.to_be_bytes())
        }
        WalOp::CloneVolume { new_ord, .. } => xxh3_64(&new_ord.to_be_bytes()),
        // FreePbas applies global-shape changes to the refcount table
        // and isn't routable on a single lane; the caller forces it into
        // the global lane via [`OpFootprint::global = true`] (see
        // `op_footprint`).
        WalOp::FreePbas { vol_ord, .. } => xxh3_64(&vol_ord.to_be_bytes()),
        // PromotionChunk / PromotionComplete are global-footprint
        // lifecycle ops (same reason as FreePbas: they mutate the
        // refcount table + the in-memory manifest's lineage edges).
        // The lane key is used only to pick a WAL writer lane; we hash
        // by vol_ord so different volumes' walker commits can fan out.
        WalOp::PromotionChunk { vol_ord, .. }
        | WalOp::PromotionComplete { vol_ord } => xxh3_64(&vol_ord.to_be_bytes()),
    }
}

#[cfg(any(target_os = "linux", target_os = "android"))]
fn thread_cpu_time() -> Option<std::time::Duration> {
    let mut ts = std::mem::MaybeUninit::<libc::timespec>::uninit();
    let rc = unsafe { libc::clock_gettime(libc::CLOCK_THREAD_CPUTIME_ID, ts.as_mut_ptr()) };
    if rc != 0 {
        return None;
    }
    let ts = unsafe { ts.assume_init() };
    Some(std::time::Duration::new(
        ts.tv_sec as u64,
        ts.tv_nsec as u32,
    ))
}

#[cfg(not(any(target_os = "linux", target_os = "android")))]
fn thread_cpu_time() -> Option<std::time::Duration> {
    None
}

fn duration_us(duration: std::time::Duration) -> u64 {
    duration.as_micros().min(u128::from(u64::MAX)) as u64
}

fn dispatch_ready(state: &DispatchState, lsn: Lsn) -> bool {
    let Some(entry) = state.pending.get(&lsn) else {
        return false;
    };
    entry.durable
        && state
            .pending
            .range(..lsn)
            .all(|(_, lower)| !entry.footprint.conflicts(&lower.footprint))
}

impl Db {
    // -------- transaction / commit --------------------------------------

    /// Start a new transaction that buffers ops until `commit()`.
    pub fn begin(&self) -> Transaction<'_> {
        Transaction::new(self)
    }

    /// LSN of the most recent successful commit.
    pub fn last_applied_lsn(&self) -> Lsn {
        *self.last_applied_lsn.lock()
    }

    fn enter_active_apply(&self, lsn: Lsn) -> ActiveApplyGuard<'_> {
        self.active_apply_lsns.lock().insert(lsn);
        ActiveApplyGuard { db: self, lsn }
    }

    fn has_higher_active_apply(&self, lsn: Lsn) -> bool {
        self.active_apply_lsns
            .lock()
            .iter()
            .next_back()
            .is_some_and(|active| *active > lsn)
    }

    fn acquire_commit_apply_gate(&self, lsn: Lsn) -> crate::apply_gate::ReadGuard<'_> {
        const RECHECK: std::time::Duration = std::time::Duration::from_micros(100);

        let started = std::time::Instant::now();
        let mut logged_wait = false;
        loop {
            if !self.apply_gate.has_writer_pending() {
                return self.apply_gate.read();
            }

            if self.has_higher_active_apply(lsn) {
                let waited = started.elapsed();
                if waited >= std::time::Duration::from_millis(1) {
                    tracing::debug!(
                        lsn,
                        wait_us = duration_us(waited),
                        "metadb: lower-LSN commit bypassing pending checkpoint to unblock global apply order"
                    );
                }
                return self.apply_gate.read_bypass_writer_pending();
            }

            if !logged_wait && started.elapsed() >= std::time::Duration::from_secs(1) {
                logged_wait = true;
                tracing::warn!(
                    lsn,
                    wait_ms = started.elapsed().as_millis() as u64,
                    "metadb: commit waiting behind checkpoint apply gate"
                );
            }
            std::thread::sleep(RECHECK);
        }
    }

    /// Internal: submit a set of ops to the WAL, apply them to indexes,
    /// and return the assigned LSN plus any per-op outcomes.
    ///
    /// Concurrency: WAL submission runs **outside** any Db-level lock so
    /// multiple submitters coalesce into one group-commit batch at the
    /// WAL writer. After fsync, dispatch is re-serialised by global LSN
    /// but does only short enqueue work: bucket ops, push each bucket into
    /// its shard lane, and advance `last_dispatched_lsn`. The expensive
    /// apply work then runs concurrently across lanes. A commit only waits
    /// for global LSN order again after its lanes finish, right before it
    /// advances the contiguous `last_applied_lsn`.
    pub(crate) fn commit_ops(&self, ops: &[WalOp]) -> Result<(Lsn, Vec<ApplyOutcome>)> {
        if ops.is_empty() {
            self.metrics.record_commit_empty();
            return Ok((self.last_applied_lsn(), Vec::new()));
        }
        let commit_started = std::time::Instant::now();
        let cpu_started = thread_cpu_time();
        let mut timing = CommitTiming::default();
        self.metrics.record_commit_attempt(ops.len());
        // `drop_gate.read()` pairs with lifecycle paths' write acquire.
        // Hold it across submit + apply so `drop_snapshot` /
        // `range_delete` cannot wedge themselves between our LSN
        // assignment and apply. Using the read side is important:
        // ordinary commits must still submit concurrently so the WAL
        // writer can coalesce them into group commits.
        let drop_gate_started = std::time::Instant::now();
        let _drop_guard = self.drop_gate.read();
        timing.drop_gate_wait = drop_gate_started.elapsed();
        self.metrics
            .record_commit_drop_gate_wait(timing.drop_gate_wait);
        // Plan the lane footprint before LSN allocation. `submit_wal_ops`
        // registers this footprint while the WAL set still holds its
        // allocator mutex, so every lower LSN's footprint is known before
        // a higher LSN can be assigned.
        let unlogged_commit_guard = if self.unlogged_commits_enabled {
            let unlogged_gate_started = std::time::Instant::now();
            let guard = self.unlogged_commit_gate.write();
            self.metrics
                .record_commit_unlogged_gate_wait(unlogged_gate_started.elapsed());
            let checkpoint_started = std::time::Instant::now();
            self.checkpoint_unlogged_before_wal_commit()?;
            self.metrics
                .record_commit_checkpoint_unlogged(checkpoint_started.elapsed());
            Some(guard)
        } else {
            None
        };
        let plan_started = std::time::Instant::now();
        let volumes = self.volumes.read().clone();
        let serial_apply = self.batch_uses_serial_apply(ops);
        let plan = if serial_apply {
            None
        } else {
            match self.build_lane_dispatch_plan(&volumes, ops) {
                Ok(plan) => Some(plan),
                Err(err) => {
                    self.metrics.record_commit_error(commit_started.elapsed());
                    self.poison_commit_waiters(&err);
                    return Err(err);
                }
            }
        };
        timing.plan = plan_started.elapsed();
        self.metrics.record_commit_plan(timing.plan);
        let plan_l2p_lanes = plan.as_ref().map(|plan| plan.l2p_sorted.len()).unwrap_or(0);
        let plan_rc_lanes = plan
            .as_ref()
            .map(|plan| {
                plan.rc_enqueued
                    .iter()
                    .filter(|enqueued| **enqueued)
                    .count()
            })
            .unwrap_or(0);
        let plan_dedup_ops = plan
            .as_ref()
            .map(|plan| {
                plan.dedup_buckets
                    .iter()
                    .map(|bucket| bucket.len())
                    .sum::<usize>()
            })
            .unwrap_or(0);
        let dispatch_footprint = plan
            .as_ref()
            .map(DispatchFootprint::from_lane_plan)
            .unwrap_or_else(DispatchFootprint::global);
        let dispatch_lanes = dispatch_footprint.lanes.len();

        let encode_started = std::time::Instant::now();
        let body = match try_encode_body(ops) {
            Ok(body) => body,
            Err(err) => {
                self.metrics.record_commit_error(commit_started.elapsed());
                return Err(err);
            }
        };
        timing.encode = encode_started.elapsed();
        self.metrics.record_commit_encode(timing.encode);
        self.metrics.record_commit_wal_body_bytes(body.len());
        let wal_started = std::time::Instant::now();
        let lsn = match self.submit_wal_ops(ops, body, Some(dispatch_footprint)) {
            Ok(lsn) => {
                timing.wal_submit = wal_started.elapsed();
                self.metrics.record_commit_wal_submit(timing.wal_submit);
                lsn
            }
            Err(err) => {
                timing.wal_submit = wal_started.elapsed();
                self.metrics.record_commit_wal_submit(timing.wal_submit);
                self.metrics.record_commit_error(commit_started.elapsed());
                self.poison_commit_waiters(&err);
                return Err(err);
            }
        };
        drop(unlogged_commit_guard);
        if let Err(err) = self.faults.inject(FaultPoint::CommitPostWalBeforeApply) {
            self.metrics.record_commit_error(commit_started.elapsed());
            self.poison_commit_waiters(&err);
            return Err(err);
        }

        // Wait until every lower durable-or-in-flight LSN that touches one
        // of our lanes has dispatched. Disjoint lower LSNs do not block us.
        let wait_started = std::time::Instant::now();
        if let Err(err) = self.mark_wal_durable_and_wait_for_dispatch(lsn) {
            timing.dispatch_wait = wait_started.elapsed();
            self.metrics.record_commit_apply_wait(timing.dispatch_wait);
            self.metrics.record_commit_error(commit_started.elapsed());
            return Err(err);
        }
        timing.dispatch_wait = wait_started.elapsed();
        self.metrics.record_commit_apply_wait(timing.dispatch_wait);

        self.finish_commit_apply(
            lsn,
            CommitApplyContext {
                commit_started,
                cpu_started,
                timing,
                volumes,
                serial_apply,
                plan,
                plan_l2p_lanes,
                plan_rc_lanes,
                plan_dedup_ops,
                dispatch_lanes,
                ops,
            },
            "metadb: slow commit_with_outcomes (>=1s)",
        )
    }

    /// Experimental: apply a batch without writing a WAL record.
    ///
    /// The caller must keep its own durable replay source until a later
    /// metadb checkpoint makes this LSN durable. Onyx uses LV2 write-buffer
    /// entries for that source.
    pub fn commit_ops_unlogged(&self, ops: &[WalOp]) -> Result<(Lsn, Vec<ApplyOutcome>)> {
        if ops.is_empty() {
            self.metrics.record_commit_empty();
            return Ok((self.last_applied_lsn(), Vec::new()));
        }
        if !self.unlogged_commits_enabled {
            return Err(MetaDbError::InvalidArgument(
                "unlogged commits are disabled in this metadb config".into(),
            ));
        }
        let commit_started = std::time::Instant::now();
        let cpu_started = thread_cpu_time();
        let mut timing = CommitTiming::default();
        self.metrics.record_commit_attempt(ops.len());

        let drop_gate_started = std::time::Instant::now();
        let _drop_guard = self.drop_gate.read();
        timing.drop_gate_wait = drop_gate_started.elapsed();
        self.metrics
            .record_commit_drop_gate_wait(timing.drop_gate_wait);
        let unlogged_gate_started = std::time::Instant::now();
        let _unlogged_commit_guard = self.unlogged_commit_gate.read();
        self.metrics
            .record_commit_unlogged_gate_wait(unlogged_gate_started.elapsed());

        let plan_started = std::time::Instant::now();
        let volumes = self.volumes.read().clone();
        let serial_apply = self.batch_uses_serial_apply(ops);
        let plan = if serial_apply {
            None
        } else {
            match self.build_lane_dispatch_plan(&volumes, ops) {
                Ok(plan) => Some(plan),
                Err(err) => {
                    self.metrics.record_commit_error(commit_started.elapsed());
                    self.poison_commit_waiters(&err);
                    return Err(err);
                }
            }
        };
        timing.plan = plan_started.elapsed();
        self.metrics.record_commit_plan(timing.plan);
        let plan_l2p_lanes = plan.as_ref().map(|plan| plan.l2p_sorted.len()).unwrap_or(0);
        let plan_rc_lanes = plan
            .as_ref()
            .map(|plan| {
                plan.rc_enqueued
                    .iter()
                    .filter(|enqueued| **enqueued)
                    .count()
            })
            .unwrap_or(0);
        let plan_dedup_ops = plan
            .as_ref()
            .map(|plan| {
                plan.dedup_buckets
                    .iter()
                    .map(|bucket| bucket.len())
                    .sum::<usize>()
            })
            .unwrap_or(0);
        let dispatch_footprint = plan
            .as_ref()
            .map(DispatchFootprint::from_lane_plan)
            .unwrap_or_else(DispatchFootprint::global);
        let dispatch_lanes = dispatch_footprint.lanes.len();

        let dispatch_started = std::time::Instant::now();
        let lsn = match self.wal.reserve_unlogged(|lsn| {
            self.register_dispatch_intent(lsn, dispatch_footprint);
        }) {
            Ok(lsn) => lsn,
            Err(err) => {
                self.metrics.record_commit_error(commit_started.elapsed());
                self.poison_commit_waiters(&err);
                return Err(err);
            }
        };
        if let Err(err) = self.mark_wal_durable_and_wait_for_dispatch(lsn) {
            timing.dispatch_wait = dispatch_started.elapsed();
            self.metrics.record_commit_apply_wait(timing.dispatch_wait);
            self.metrics.record_commit_error(commit_started.elapsed());
            return Err(err);
        }
        timing.dispatch_wait = dispatch_started.elapsed();
        self.metrics.record_commit_apply_wait(timing.dispatch_wait);

        let result = self.finish_commit_apply(
            lsn,
            CommitApplyContext {
                commit_started,
                cpu_started,
                timing,
                volumes,
                serial_apply,
                plan,
                plan_l2p_lanes,
                plan_rc_lanes,
                plan_dedup_ops,
                dispatch_lanes,
                ops,
            },
            "metadb: slow unlogged commit_with_outcomes (>=1s)",
        );
        if result.is_ok() {
            let mut pending = self.unlogged_pending_lsn.lock();
            *pending = Some(pending.map_or(lsn, |prev| prev.max(lsn)));
        }
        result
    }

    fn finish_commit_apply(
        &self,
        lsn: Lsn,
        mut ctx: CommitApplyContext<'_>,
        slow_message: &'static str,
    ) -> Result<(Lsn, Vec<ApplyOutcome>)> {
        let apply_gate_started = std::time::Instant::now();
        let apply_guard = self.acquire_commit_apply_gate(lsn);
        let read_held_started = std::time::Instant::now();
        let active_apply = self.enter_active_apply(lsn);
        ctx.timing.apply_gate_wait = apply_gate_started.elapsed();
        self.metrics
            .record_commit_apply_gate_wait(ctx.timing.apply_gate_wait);

        let apply_started = std::time::Instant::now();
        let outcomes = if let Some(plan) = ctx.plan {
            let enqueue_started = std::time::Instant::now();
            let queued_plan =
                self.enqueue_lane_plan(&ctx.volumes, lsn, plan, Arc::new(ctx.ops.to_vec()));
            ctx.timing.lane_enqueue = enqueue_started.elapsed();
            match self.apply_ops_laned(lsn, ctx.ops.len(), queued_plan) {
                Ok((outcomes, laned_timing)) => {
                    ctx.timing.apply = apply_started.elapsed();
                    ctx.timing.laned = laned_timing;
                    self.metrics.record_commit_apply(ctx.timing.apply);
                    self.metrics.record_commit_apply_laned(
                        laned_timing.l2p_wait,
                        laned_timing.rc_enqueue,
                        laned_timing.rc_wait,
                        laned_timing.dedup_enqueue,
                        laned_timing.dedup_wait,
                    );
                    outcomes
                }
                Err(err) => {
                    ctx.timing.apply = apply_started.elapsed();
                    self.metrics.record_commit_apply(ctx.timing.apply);
                    self.metrics
                        .record_commit_error(ctx.commit_started.elapsed());
                    self.poison_commit_waiters(&err);
                    return Err(err);
                }
            }
        } else {
            if let Err(err) = self.wait_for_global_apply_turn(lsn) {
                ctx.timing.apply = apply_started.elapsed();
                self.metrics.record_commit_apply(ctx.timing.apply);
                self.metrics
                    .record_commit_error(ctx.commit_started.elapsed());
                return Err(err);
            }
            match self.apply_commit_batch(&ctx.volumes, lsn, ctx.ops) {
                Ok(outcomes) => {
                    ctx.timing.apply = apply_started.elapsed();
                    self.metrics.record_commit_apply(ctx.timing.apply);
                    outcomes
                }
                Err(err) => {
                    ctx.timing.apply = apply_started.elapsed();
                    self.metrics.record_commit_apply(ctx.timing.apply);
                    self.metrics
                        .record_commit_error(ctx.commit_started.elapsed());
                    self.poison_commit_waiters(&err);
                    return Err(err);
                }
            }
        };
        if let Err(err) = self.faults.inject(FaultPoint::CommitPostApplyBeforeLsnBump) {
            self.metrics
                .record_commit_error(ctx.commit_started.elapsed());
            self.poison_commit_waiters(&err);
            return Err(err);
        }

        let finish_started = std::time::Instant::now();
        if let Err(err) = self.finish_global_apply(lsn) {
            self.metrics
                .record_commit_error(ctx.commit_started.elapsed());
            return Err(err);
        }
        ctx.timing.finish_global_wait = finish_started.elapsed();
        self.metrics
            .record_commit_finish_global_wait(ctx.timing.finish_global_wait);
        if ctx.serial_apply {
            self.complete_retained_dispatch(lsn);
        }
        drop(active_apply);
        drop(apply_guard);
        self.metrics
            .record_commit_read_held(read_held_started.elapsed());

        let total_elapsed = ctx.commit_started.elapsed();
        if total_elapsed >= std::time::Duration::from_secs(1) {
            let cpu_elapsed = ctx
                .cpu_started
                .and_then(|started| thread_cpu_time().map(|now| now.saturating_sub(started)));
            let pending = self.pending_state();
            let metrics = self.metrics.snapshot();
            tracing::warn!(
                lsn,
                ops = ctx.ops.len(),
                serial_apply = ctx.serial_apply,
                plan_l2p_lanes = ctx.plan_l2p_lanes,
                plan_rc_lanes = ctx.plan_rc_lanes,
                plan_dedup_ops = ctx.plan_dedup_ops,
                dispatch_lanes = ctx.dispatch_lanes,
                total_ms = total_elapsed.as_millis() as u64,
                thread_cpu_ms = cpu_elapsed.map(|d| d.as_millis() as u64),
                drop_gate_wait_us = duration_us(ctx.timing.drop_gate_wait),
                plan_us = duration_us(ctx.timing.plan),
                encode_us = duration_us(ctx.timing.encode),
                wal_submit_us = duration_us(ctx.timing.wal_submit),
                dispatch_wait_us = duration_us(ctx.timing.dispatch_wait),
                apply_gate_wait_us = duration_us(ctx.timing.apply_gate_wait),
                lane_enqueue_us = duration_us(ctx.timing.lane_enqueue),
                apply_us = duration_us(ctx.timing.apply),
                l2p_lane_wait_us = duration_us(ctx.timing.laned.l2p_wait),
                rc_lane_enqueue_us = duration_us(ctx.timing.laned.rc_enqueue),
                rc_lane_wait_us = duration_us(ctx.timing.laned.rc_wait),
                dedup_lane_enqueue_us = duration_us(ctx.timing.laned.dedup_enqueue),
                dedup_lane_wait_us = duration_us(ctx.timing.laned.dedup_wait),
                finish_global_wait_us = duration_us(ctx.timing.finish_global_wait),
                wal_submit_wait_max_us = metrics.wal_submit_wait_max_us,
                wal_write_max_us = metrics.wal_write_max_us,
                wal_fsync_max_us = metrics.wal_fsync_max_us,
                wal_batch_records_max = metrics.wal_batch_records_max,
                pending_dispatch = pending.dispatch_pending,
                pending_dedup_lane_q = pending.dedup_lane_queue,
                pending_l2p_apply_q = pending.l2p_apply_queue,
                pending_l2p_dirty = pending.l2p_pagebuf_dirty,
                pending_rc_apply_q = pending.rc_apply_queue,
                pending_rc_dirty = pending.rc_pagebuf_dirty,
                flush_total_max_us = metrics.flush_total_max_us,
                flush_io_max_us = metrics.flush_io_max_us,
                flush_install_max_us = metrics.flush_install_max_us,
                flush_reclaim_max_us = metrics.flush_reclaim_max_us,
                slow_message
            );
        }
        self.metrics.record_commit_success(total_elapsed);
        Ok((lsn, outcomes))
    }

    fn checkpoint_unlogged_before_wal_commit(&self) -> Result<()> {
        if self.unlogged_pending_lsn.lock().is_none() {
            return Ok(());
        }
        self.flush()?;
        Ok(())
    }

    fn apply_op(
        &self,
        volumes: &HashMap<VolumeOrdinal, Arc<Volume>>,
        lsn: Lsn,
        op: &WalOp,
    ) -> Result<ApplyOutcome> {
        let snap_lookup = |vol: VolumeOrdinal| -> Vec<SnapInfo> { self.snap_info_for_vol(vol) };
        let op_started = std::time::Instant::now();
        let outcome = apply_op_bare(
            volumes,
            &self.refcount_shards,
            &self.dedup_index,
            &self.page_store,
            lsn,
            op,
            &snap_lookup,
        )?;
        record_per_op_apply(&self.metrics, op, op_started.elapsed());
        // DropSnapshot also mutates the in-memory manifest's snapshot
        // list; the page work lives in apply_op_bare so it can be
        // shared with the replay path. Lock order (apply_gate.read →
        // manifest_state) matches every other call site.
        if let WalOp::DropSnapshot { id, .. } = op {
            let dropped_vol = {
                let mut mstate = self.manifest_state.lock();
                let dropped = mstate
                    .manifest
                    .snapshots
                    .iter()
                    .find(|s| s.id == *id)
                    .map(|s| s.vol_ord);
                mstate.manifest.snapshots.retain(|s| s.id != *id);
                dropped
            };
            if let Some(vol) = dropped_vol {
                self.recompute_snap_info(vol);
            }
        }
        // Phase 4 Step 5: mirror walker-driven manifest mutations into
        // `manifest_state` so the next checkpoint persists them. The
        // bare layer already advanced `Volume::promotion_cursor` /
        // cleared `parent_vol_ord`; here we propagate the same change
        // into the in-memory manifest. Lock order: apply_gate.read →
        // manifest_state (same as DropSnapshot).
        match op {
            WalOp::PromotionChunk {
                vol_ord,
                next_cursor,
                ..
            } => {
                let mut mstate = self.manifest_state.lock();
                if let Some(entry) =
                    mstate.manifest.volumes.iter_mut().find(|e| e.ord == *vol_ord)
                {
                    entry.promotion_cursor = *next_cursor;
                }
            }
            WalOp::PromotionComplete { vol_ord } => {
                let mut mstate = self.manifest_state.lock();
                if let Some(entry) =
                    mstate.manifest.volumes.iter_mut().find(|e| e.ord == *vol_ord)
                {
                    entry.parent_vol_ord = None;
                    entry.promotion_cursor = None;
                }
            }
            _ => {}
        }
        Ok(outcome)
    }

    pub(super) fn submit_wal_ops(
        &self,
        ops: &[WalOp],
        body: Vec<u8>,
        footprint: Option<DispatchFootprint>,
    ) -> Result<Lsn> {
        let lane = self.wal_lane_for_ops(ops);
        match footprint {
            Some(footprint) => self.wal.submit_to_reserved(lane, body, |lsn| {
                self.register_dispatch_intent(lsn, footprint);
            }),
            None => self.wal.submit_to(lane, body),
        }
    }

    fn wal_lane_for_ops(&self, ops: &[WalOp]) -> usize {
        let lanes = self.wal.lane_count();
        if lanes <= 1 {
            return 0;
        }
        let Some(op) = ops.first() else {
            return 0;
        };
        (wal_lane_key(op) as usize) % lanes
    }

    /// Apply a commit batch under `apply_gate.read()`. Large batches
    /// group ops by shard so each shard lock is taken once per (vol,
    /// shard) rather than once per op. Small batches fall through to
    /// the serial path — the bucketing overhead dominates below a
    /// handful of ops.
    ///
    /// Correctness:
    /// - Intra-bucket order is preserved (`Vec<usize>` of original op
    ///   indices), so multiple ops to the same (vol, lba) or same pba
    ///   apply in caller order.
    /// - Cross-bucket order is relaxed: L2P shards and refcount shards
    ///   live on disjoint trees, and same-LSN `cow_for_write` is
    ///   idempotent via `page.generation >= lsn`, so reordering between
    ///   two shards does not change the committed state.
    /// - Each shard lock is held for the span of its bucket only;
    ///   locks are taken one at a time in (vol_ord, shard_id) sorted
    ///   order, so the CLAUDE-documented "cross-shard ops take locks
    ///   in shard index order" invariant still holds.
    ///
    /// Defensive fallback: if the batch contains a lifecycle op
    /// (DropSnapshot, CreateVolume, DropVolume, CloneVolume), a guarded
    /// remap, or a remap against a volume with live snapshots, we fall
    /// back to serial apply. Lifecycle ops do not currently reach
    /// `commit_ops` from any caller — they have their own entry points
    /// with stronger locking — but the fallback keeps the bucketed path
    /// safe if a future caller routes them through here.
    fn apply_commit_batch(
        &self,
        volumes: &HashMap<VolumeOrdinal, Arc<Volume>>,
        lsn: Lsn,
        ops: &[WalOp],
    ) -> Result<Vec<ApplyOutcome>> {
        const BUCKET_THRESHOLD: usize = 8;
        if ops.len() < BUCKET_THRESHOLD || self.batch_requires_serial_apply(ops) {
            let mut outcomes = Vec::with_capacity(ops.len());
            for op in ops {
                outcomes.push(self.apply_op(volumes, lsn, op)?);
            }
            return Ok(outcomes);
        }
        self.apply_ops_grouped(volumes, lsn, ops)
    }

    fn batch_requires_serial_apply(&self, ops: &[WalOp]) -> bool {
        if batch_contains_lifecycle_op(ops) {
            return true;
        }

        // Guarded remaps used to fall back to serial apply because the
        // lane path's `apply_l2p_bucket` did not honour the guard. The
        // bucket now does the rc check inline (same lock order as the
        // serial path: L2P shard write → refcount shard lock), so guard
        // alone no longer forces serial. Snapshot-bearing volumes still
        // need the serial path for the snap-pin walk inside
        // `apply_l2p_remap` / `apply_l2p_remap_range` — the lane
        // path's leaf-run primitives do not consult `snap_infos`.
        let mut remap_vols = HashSet::new();
        for op in ops {
            match op {
                WalOp::L2pRemap { vol_ord, .. }
                | WalOp::L2pRemapRange { vol_ord, .. } => {
                    remap_vols.insert(*vol_ord);
                }
                _ => {}
            }
        }

        remap_vols
            .into_iter()
            .any(|vol_ord| !self.snap_info_for_vol(vol_ord).is_empty())
    }

    fn batch_uses_serial_apply(&self, ops: &[WalOp]) -> bool {
        // B2: laned `apply_l2p_bucket` is buffer-aware (see
        // `apply_l2p_bucket_buffer`); the buffer path no longer forces
        // serial. Snapshot-bearing volumes still need serial via the
        // unchanged `batch_requires_serial_apply` rule (snap-pin walk
        // lives in `apply_l2p_remap`).
        self.batch_requires_serial_apply(ops)
    }

    pub(super) fn poison_commit_waiters(&self, err: &MetaDbError) {
        let mut poison = self.commit_poison.lock();
        if poison.is_none() {
            *poison = Some(err.to_string());
        }
        self.dispatch_cvar.notify_all();
        self.commit_cvar.notify_all();
    }

    fn commit_poison_error(&self) -> Option<MetaDbError> {
        self.commit_poison
            .lock()
            .as_ref()
            .map(|msg| MetaDbError::Corruption(format!("commit pipeline failed: {msg}")))
    }

    fn register_dispatch_intent(&self, lsn: Lsn, footprint: DispatchFootprint) {
        let mut state = self.dispatch_state.lock();
        let old = state.pending.insert(
            lsn,
            DispatchEntry {
                footprint,
                durable: false,
            },
        );
        debug_assert!(
            old.is_none(),
            "duplicate dispatch reservation for LSN {lsn}"
        );
        self.dispatch_cvar.notify_all();
    }

    fn mark_wal_durable_and_wait_for_dispatch(&self, lsn: Lsn) -> Result<()> {
        let mut state = self.dispatch_state.lock();
        let entry = state.pending.get_mut(&lsn).ok_or_else(|| {
            MetaDbError::Corruption(format!("missing dispatch reservation for LSN {lsn}"))
        })?;
        entry.durable = true;
        self.dispatch_cvar.notify_all();

        loop {
            if let Some(err) = self.commit_poison_error() {
                return Err(err);
            }
            if dispatch_ready(&state, lsn) {
                return Ok(());
            }
            self.dispatch_cvar.wait(&mut state);
        }
    }

    fn forget_dispatch_intent(&self, lsn: Lsn) {
        let mut state = self.dispatch_state.lock();
        state.pending.remove(&lsn);
        self.dispatch_cvar.notify_all();
    }

    fn complete_retained_dispatch(&self, lsn: Lsn) {
        self.forget_dispatch_intent(lsn);
    }

    pub(super) fn advance_dispatch_lsn(&self, lsn: Lsn) {
        // Lifecycle paths still call this at the old "dispatch complete"
        // point. They hold `drop_gate.write()` and `apply_gate.write()`,
        // so ordinary commits cannot have in-flight dispatch reservations
        // that need ordering against them.
        self.forget_dispatch_intent(lsn);
    }

    pub(super) fn wait_for_global_apply_turn(&self, lsn: Lsn) -> Result<()> {
        let mut applied = self.last_applied_lsn.lock();
        while *applied + 1 < lsn {
            if let Some(err) = self.commit_poison_error() {
                return Err(err);
            }
            self.commit_cvar.wait(&mut applied);
        }
        Ok(())
    }

    pub(super) fn finish_global_apply(&self, lsn: Lsn) -> Result<()> {
        let mut applied = self.last_applied_lsn.lock();
        while *applied + 1 < lsn {
            if let Some(err) = self.commit_poison_error() {
                return Err(err);
            }
            self.commit_cvar.wait(&mut applied);
        }
        debug_assert_eq!(
            *applied + 1,
            lsn,
            "global apply LSN advanced non-contiguously"
        );
        *applied = lsn;
        self.commit_cvar.notify_all();
        Ok(())
    }

    fn build_lane_dispatch_plan(
        &self,
        volumes: &HashMap<VolumeOrdinal, Arc<Volume>>,
        ops: &[WalOp],
    ) -> Result<LaneDispatchPlan> {
        let mut l2p_buckets: HashMap<(VolumeOrdinal, usize), Vec<L2pBucketEntry>> = HashMap::new();
        let mut rc_buckets: Vec<Vec<RcApplyAction>> = (0..self.refcount_shards.len())
            .map(|_| Vec::new())
            .collect();
        let dedup_shard_count = self.dedup_lanes.len();
        let dedup_shard_count_u32 = dedup_shard_count as u32;
        let mut dedup_buckets: Vec<Vec<usize>> =
            (0..dedup_shard_count).map(|_| Vec::new()).collect();
        let mut remap_may_defer_refcount = false;

        for (idx, op) in ops.iter().enumerate() {
            match op {
                WalOp::L2pPut { vol_ord, lba, .. } | WalOp::L2pDelete { vol_ord, lba } => {
                    let volume = volumes.get(vol_ord).ok_or_else(|| {
                        MetaDbError::Corruption(format!("L2P op for unknown volume ord {vol_ord}"))
                    })?;
                    let sid = shard_for_key_l2p(&volume.shards, *lba);
                    l2p_buckets
                        .entry((*vol_ord, sid))
                        .or_default()
                        .push(L2pBucketEntry::Single(idx));
                }
                WalOp::L2pRemap { vol_ord, lba, .. } => {
                    let volume = volumes.get(vol_ord).ok_or_else(|| {
                        MetaDbError::Corruption(format!(
                            "L2pRemap for unknown volume ord {vol_ord}"
                        ))
                    })?;
                    let sid = shard_for_key_l2p(&volume.shards, *lba);
                    l2p_buckets
                        .entry((*vol_ord, sid))
                        .or_default()
                        .push(L2pBucketEntry::Single(idx));
                    remap_may_defer_refcount = true;
                }
                WalOp::L2pRemapRange {
                    vol_ord,
                    start_lba,
                    values,
                } => {
                    let volume = volumes.get(vol_ord).ok_or_else(|| {
                        MetaDbError::Corruption(format!(
                            "L2pRemapRange for unknown volume ord {vol_ord}"
                        ))
                    })?;
                    // Count one range op now; per-shard LBA contribution
                    // (lbas + us) is recorded inside apply_l2p_bucket via
                    // record_apply_l2p_remap_range_lane_work.
                    self.metrics.record_apply_l2p_remap_range_lane_ops(1);
                    // Group LBA offsets by L2P shard. Typical
                    // passthrough range (32 contiguous LBAs aligned on
                    // a 128-LBA leaf) lands in one shard; mis-aligned
                    // ranges land in 1-2 shards. Each shard's slice
                    // becomes one `RangeSlice` bucket entry sharing
                    // the same `op_idx` — the outcomes merger combines
                    // the partial `ApplyOutcome::L2pRemapRange`s.
                    let mut per_shard: HashMap<usize, Vec<u32>> = HashMap::new();
                    for off in 0..values.len() {
                        let lba = start_lba + off as u64;
                        let sid = shard_for_key_l2p(&volume.shards, lba);
                        per_shard.entry(sid).or_default().push(off as u32);
                    }
                    for (sid, offsets) in per_shard {
                        l2p_buckets
                            .entry((*vol_ord, sid))
                            .or_default()
                            .push(L2pBucketEntry::RangeSlice {
                                op_idx: idx,
                                lba_offsets: offsets.into_boxed_slice(),
                            });
                    }
                    remap_may_defer_refcount = true;
                }
                WalOp::DedupPut { hash, .. }
                | WalOp::DedupPutGuarded { hash, .. }
                | WalOp::DedupDelete { hash, .. }
                | WalOp::DedupCompareDelete { hash, .. }
                | WalOp::DedupComparePut { hash, .. } => {
                    let sid =
                        crate::dedup_types::shard_for_hash(hash, dedup_shard_count_u32) as usize;
                    dedup_buckets[sid].push(idx);
                }
                WalOp::DropSnapshot { .. }
                | WalOp::CreateVolume { .. }
                | WalOp::DropVolume { .. }
                | WalOp::CloneVolume { .. }
                | WalOp::L2pRangeDelete { .. }
                | WalOp::FreePbas { .. }
                | WalOp::PromotionChunk { .. }
                | WalOp::PromotionComplete { .. } => {
                    return Err(MetaDbError::Corruption(
                        "lifecycle op reached lane dispatch path".into(),
                    ));
                }
            }
        }

        let mut l2p_sorted: Vec<_> = l2p_buckets.into_iter().collect();
        l2p_sorted.sort_by_key(|((vol, sid), _)| (*vol, *sid));

        let mut rc_enqueued: Vec<bool> =
            rc_buckets.iter().map(|bucket| !bucket.is_empty()).collect();
        if remap_may_defer_refcount {
            rc_enqueued.fill(true);
        }

        Ok(LaneDispatchPlan {
            l2p_sorted,
            rc_buckets,
            rc_enqueued,
            dedup_buckets,
        })
    }

    fn enqueue_lane_plan(
        &self,
        volumes: &HashMap<VolumeOrdinal, Arc<Volume>>,
        lsn: Lsn,
        plan: LaneDispatchPlan,
        ops: Arc<Vec<WalOp>>,
    ) -> QueuedLanePlan {
        let mut l2p_receivers = Vec::with_capacity(plan.l2p_sorted.len());
        // Snapshot refcount shard handles once per commit so the per-lane
        // closures can do guarded-remap rc lookups (dedup hits) without
        // touching the Db struct from the worker thread.
        let refcount_shards_arc: Arc<Vec<Arc<crate::refcount::RcShard>>> =
            Arc::new(self.refcount_shards.iter().map(|s| s.rc.clone()).collect());
        for ((vol_ord, sid), indices) in plan.l2p_sorted {
            let volume = volumes
                .get(&vol_ord)
                .expect("volume presence checked during lane planning");
            let apply_volume = volume.clone();
            let apply_ops = ops.clone();
            let metrics = self.metrics.clone();
            let refcount_shards_arc = refcount_shards_arc.clone();
            let (tx, rx) = crossbeam_channel::bounded(1);
            volume.shards[sid].apply_lane.enqueue_ready(
                lsn,
                Box::new(move || {
                    let result = Self::apply_l2p_bucket(
                        apply_volume,
                        sid,
                        indices,
                        lsn,
                        apply_ops.as_slice(),
                        refcount_shards_arc.as_slice(),
                        metrics.as_ref(),
                    );
                    let _ = tx.send(result);
                }),
            );
            l2p_receivers.push(rx);
        }
        // One pending slot per non-empty dedup bucket. Empty buckets
        // get `None`, matching the per-shard layout of `dedup_buckets`.
        let mut dedup_pendings: Vec<Option<PendingApplyWork>> =
            (0..plan.dedup_buckets.len()).map(|_| None).collect();
        for (sid, bucket) in plan.dedup_buckets.iter().enumerate() {
            if !bucket.is_empty() {
                dedup_pendings[sid] = Some(self.dedup_lanes[sid].enqueue_pending(lsn));
            }
        }
        QueuedLanePlan {
            ops,
            l2p_receivers,
            rc_buckets: plan.rc_buckets,
            dedup_buckets: plan.dedup_buckets,
            dedup_pendings,
        }
    }

    fn apply_l2p_bucket(
        volume: Arc<Volume>,
        sid: usize,
        indices: Vec<L2pBucketEntry>,
        lsn: Lsn,
        ops: &[WalOp],
        refcount_shards: &[Arc<crate::refcount::RcShard>],
        metrics: &MetaMetrics,
    ) -> Result<L2pBucketApplyResult> {
        let mut outcomes = Vec::with_capacity(indices.len());
        let mut rc_actions = Vec::new();
        let shard = &volume.shards[sid];
        if shard.use_buffer {
            return Self::apply_l2p_bucket_buffer(
                volume.clone(),
                sid,
                indices,
                lsn,
                ops,
                refcount_shards,
                metrics,
            );
        }
        let tree_lock_started = std::time::Instant::now();
        let mut tree = shard.tree.write();
        let tree_lock_wait = tree_lock_started.elapsed();
        let read_view_prepare_started = std::time::Instant::now();
        let mut read_view_guard = if shard.active_readers.load(Ordering::Acquire) == 0
            && let Some(guard) = shard.read_view.try_write()
        {
            // Holding the write guard blocks new readers until the
            // post-apply snapshot is published. Do not replace the current
            // view with an empty overlay here: the pre-apply root may already
            // reference dirty pages from earlier commits that have not been
            // checkpointed to the page store yet.
            if shard.active_readers.load(Ordering::Acquire) == 0 {
                Some(guard)
            } else {
                None
            }
        } else {
            None
        };
        let read_view_prepare = read_view_prepare_started.elapsed();
        let mut l2p_put_count = 0u64;
        let mut l2p_delete_count = 0u64;
        let mut l2p_remap_count = 0u64;
        let mut l2p_remap_range_lba_count = 0u64;
        let bucket_started = std::time::Instant::now();
        let ops_started = std::time::Instant::now();
        let ops_result = (|| -> Result<()> {
            // Stage 1.6 unification: flatten every unguarded `L2pRemap`
            // (`Single`) and every `RangeSlice` LBA into one batch list,
            // then leaf-run-batch ACROSS entry-kind boundaries. The
            // previous Stage 1.5 path leaf-run-grouped each RangeSlice
            // independently, so multiple range ops in the same bucket
            // landing on the same leaf each paid their own tree descend +
            // leaf-page modify. With sequential writes (the common
            // passthrough case) that doubled per-LBA cost vs. the baseline
            // per-LBA path.
            //
            // Layout:
            // * `batch_lbas[i] = (op_idx, lba, value, range_offset)`
            //   — `range_offset = Some(off)` flags a RangeSlice-sourced
            //   entry that should land in `range_partials[op_idx]` rather
            //   than as its own `L2pRemap` outcome.
            // * `range_partials[op_idx]` = pre-allocated
            //   `(applied, prevs)` boxes sized to the full range op (so
            //   slots in different shards land in the same positions).
            // * `nonbatch_positions` holds entries that can't leaf-run
            //   (Put/Delete/guarded L2pRemap); processed afterwards using
            //   the per-op fast paths.
            struct BatchLba {
                op_idx: usize,
                lba: u64,
                value: L2pValue,
                range_offset: Option<u32>,
            }
            let mut batch_lbas: Vec<BatchLba> = Vec::with_capacity(indices.len());
            let mut nonbatch_positions: Vec<usize> = Vec::new();
            let mut range_partials: std::collections::HashMap<
                usize,
                (Box<[bool]>, Vec<Option<L2pValue>>),
            > = std::collections::HashMap::new();

            for (pos, entry) in indices.iter().enumerate() {
                match entry {
                    L2pBucketEntry::Single(idx) => {
                        if let WalOp::L2pRemap {
                            lba,
                            new_value,
                            guard: None,
                            ..
                        } = &ops[*idx]
                        {
                            batch_lbas.push(BatchLba {
                                op_idx: *idx,
                                lba: *lba,
                                value: *new_value,
                                range_offset: None,
                            });
                        } else {
                            nonbatch_positions.push(pos);
                        }
                    }
                    L2pBucketEntry::RangeSlice { op_idx, lba_offsets } => {
                        let (start_lba, range_values) = match &ops[*op_idx] {
                            WalOp::L2pRemapRange {
                                start_lba, values, ..
                            } => (*start_lba, values.as_ref()),
                            other => unreachable!(
                                "RangeSlice op_idx points to non-range op: {other:?}"
                            ),
                        };
                        let n = range_values.len();
                        range_partials.entry(*op_idx).or_insert_with(|| {
                            (
                                vec![false; n].into_boxed_slice(),
                                vec![None; n],
                            )
                        });
                        for &off in lba_offsets.iter() {
                            batch_lbas.push(BatchLba {
                                op_idx: *op_idx,
                                lba: start_lba + off as u64,
                                value: range_values[off as usize],
                                range_offset: Some(off),
                            });
                        }
                    }
                }
            }

            // Group batch_lbas by leaf_idx. Map preserves identity by
            // index into `batch_lbas` so per-leaf processing can recover
            // (op_idx, range_offset, etc).
            let mut leaf_groups: std::collections::HashMap<u64, Vec<usize>> =
                std::collections::HashMap::new();
            for (i, b) in batch_lbas.iter().enumerate() {
                let leaf_idx = b.lba >> crate::paged::format::LEAF_SHIFT;
                leaf_groups.entry(leaf_idx).or_default().push(i);
            }
            // Sort by leaf_idx for deterministic ordering (tests, replay).
            let mut leaf_order: Vec<u64> = leaf_groups.keys().copied().collect();
            leaf_order.sort_unstable();

            for leaf_idx in leaf_order {
                let group = leaf_groups
                    .remove(&leaf_idx)
                    .expect("leaf_idx came from leaf_groups keys");
                let mut entries: Vec<(u64, L2pValue)> = Vec::with_capacity(group.len());
                let mut accepted_batch_idx: Vec<usize> = Vec::with_capacity(group.len());
                for batch_i in &group {
                    let b = &batch_lbas[*batch_i];
                    let cur = tree.get_read_only(b.lba)?;
                    if super::apply::seq_guard_rejects(b.value.seq(), cur.as_ref()) {
                        match b.range_offset {
                            Some(off) => {
                                l2p_remap_range_lba_count += 1;
                                let (_, prevs) = range_partials
                                    .get_mut(&b.op_idx)
                                    .expect("range partial pre-allocated above");
                                prevs[off as usize] = cur;
                            }
                            None => {
                                l2p_remap_count += 1;
                                outcomes.push((
                                    b.op_idx,
                                    ApplyOutcome::L2pRemap {
                                        applied: false,
                                        prev: cur,
                                        freed_pba: None,
                                    },
                                ));
                            }
                        }
                        continue;
                    }
                    entries.push((b.lba, b.value));
                    accepted_batch_idx.push(*batch_i);
                }
                if entries.is_empty() {
                    continue;
                }
                let prev_values =
                    tree.insert_leaf_run_at_lsn_deferred_finish(&entries, lsn)?;
                for ((batch_i, (_lba, _new_value)), prev) in accepted_batch_idx
                    .into_iter()
                    .zip(entries.into_iter())
                    .zip(prev_values.into_iter())
                {
                    let b = &batch_lbas[batch_i];
                    super::apply::record_dead(&volume, prev, lsn);
                    match b.range_offset {
                        Some(off) => {
                            l2p_remap_range_lba_count += 1;
                            let (applied, prevs) = range_partials
                                .get_mut(&b.op_idx)
                                .expect("range partial pre-allocated above");
                            applied[off as usize] = true;
                            prevs[off as usize] = prev;
                        }
                        None => {
                            l2p_remap_count += 1;
                            outcomes.push((
                                b.op_idx,
                                ApplyOutcome::L2pRemap {
                                    applied: true,
                                    prev,
                                    freed_pba: None,
                                },
                            ));
                        }
                    }
                }
            }

            // Finalize range_partials as L2pRemapRange outcomes. Ordering
            // is unspecified at the metadb apply layer; the
            // `apply_ops_laned` merger writes them into outcomes[idx]
            // (matching the `outcomes.len() == ops.len()` contract).
            for (op_idx, (applied, prevs)) in range_partials.drain() {
                outcomes.push((
                    op_idx,
                    ApplyOutcome::L2pRemapRange {
                        applied,
                        prevs: prevs.into_boxed_slice(),
                        freed_pbas: Vec::new(),
                    },
                ));
            }

            // Phase D: non-batchable ops (Put / Delete / guarded
            // L2pRemap). Each goes through its own tree primitive; no
            // sharing with leaf-run batching above.
            for pos in nonbatch_positions {
                let idx = match &indices[pos] {
                    L2pBucketEntry::Single(i) => *i,
                    L2pBucketEntry::RangeSlice { .. } => {
                        unreachable!("nonbatch slot contains only Single entries")
                    }
                };
                let outcome = match &ops[idx] {
                    WalOp::L2pPut { lba, value, .. } => {
                        let cur = tree.get_read_only(*lba)?;
                        if super::apply::seq_guard_rejects(value.seq(), cur.as_ref()) {
                            l2p_put_count += 1;
                            outcomes.push((idx, ApplyOutcome::L2pPrev(cur)));
                            continue;
                        }
                        let prev = tree.insert_at_lsn_deferred_finish(*lba, *value, lsn)?;
                        super::apply::record_dead(&volume, prev, lsn);
                        l2p_put_count += 1;
                        ApplyOutcome::L2pPrev(prev)
                    }
                    WalOp::L2pDelete { lba, .. } => {
                        let prev = tree.delete_at_lsn_deferred_finish(*lba, lsn)?;
                        l2p_delete_count += 1;
                        ApplyOutcome::L2pPrev(prev)
                    }
                    WalOp::L2pRemap {
                        lba,
                        new_value,
                        guard,
                        ..
                    } => {
                        // Guarded remaps (dedup hits): verify the target pba's
                        // refcount still satisfies `min_rc` before mutating
                        // L2P. Lock order matches the serial path
                        // (`apply_l2p_remap` in apply.rs): L2P shard write →
                        // refcount shard lock. Refcount lanes only ever take
                        // their own shard's lock and never touch L2P, so
                        // there is no L2P↔RC cycle.
                        if let Some((gp, min_rc)) = guard {
                            let gp_sid =
                                (xxh3_64(&gp.to_be_bytes()) as usize) % refcount_shards.len();
                            let cur = refcount_shards[gp_sid].get(*gp)?;
                            if cur < *min_rc {
                                l2p_remap_count += 1;
                                outcomes.push((
                                    idx,
                                    ApplyOutcome::L2pRemap {
                                        applied: false,
                                        prev: None,
                                        freed_pba: None,
                                    },
                                ));
                                continue;
                            }
                        }
                        let cur = tree.get_read_only(*lba)?;
                        if super::apply::seq_guard_rejects(new_value.seq(), cur.as_ref()) {
                            l2p_remap_count += 1;
                            outcomes.push((
                                idx,
                                ApplyOutcome::L2pRemap {
                                    applied: false,
                                    prev: cur,
                                    freed_pba: None,
                                },
                            ));
                            continue;
                        }
                        let prev = tree.insert_at_lsn_deferred_finish(*lba, *new_value, lsn)?;
                        super::apply::record_dead(&volume, prev, lsn);
                        l2p_remap_count += 1;
                        ApplyOutcome::L2pRemap {
                            applied: true,
                            prev,
                            freed_pba: None,
                        }
                    }
                    other => unreachable!("L2P bucket holds only L2P ops; saw {other:?}"),
                };
                outcomes.push((idx, outcome));
            }
            Ok(())
        })();
        let ops_elapsed = ops_started.elapsed();
        let finish_started = std::time::Instant::now();
        let apply_result = match ops_result {
            Ok(()) => tree.finish_batch_apply(),
            Err(err) => Err(err),
        };
        let finish_elapsed = finish_started.elapsed();
        tree.set_exclusive_read_overlay_mutation(false);
        let publish_started = std::time::Instant::now();
        if apply_result.is_ok() {
            if let Some(mut guard) = read_view_guard.take() {
                *guard = Arc::new(tree.snapshot_read_view());
            } else {
                super::apply::publish_l2p_read_view(shard, &tree);
            }
        }
        let publish_elapsed = publish_started.elapsed();
        apply_result?;
        let bucket_elapsed = bucket_started.elapsed();
        let total_l2p_ops =
            l2p_put_count + l2p_delete_count + l2p_remap_count + l2p_remap_range_lba_count;
        metrics.record_apply_l2p_bucket_stages(
            total_l2p_ops,
            bucket_elapsed,
            tree_lock_wait,
            read_view_prepare,
            ops_elapsed,
            finish_elapsed,
            publish_elapsed,
        );
        if bucket_elapsed.as_micros() >= 100_000
            || tree_lock_wait.as_micros() >= 100_000
            || read_view_prepare.as_micros() >= 100_000
            || ops_elapsed.as_micros() >= 100_000
            || publish_elapsed.as_micros() >= 100_000
        {
            tracing::warn!(
                vol_ord = volume.ord,
                shard = sid,
                lsn,
                indices = total_l2p_ops,
                put = l2p_put_count,
                delete = l2p_delete_count,
                remap = l2p_remap_count,
                range_lbas = l2p_remap_range_lba_count,
                total_us = duration_us(bucket_elapsed),
                tree_lock_wait_us = duration_us(tree_lock_wait),
                read_view_prepare_us = duration_us(read_view_prepare),
                ops_us = duration_us(ops_elapsed),
                finish_us = duration_us(finish_elapsed),
                publish_us = duration_us(publish_elapsed),
                "metadb: slow l2p apply bucket"
            );
        }
        if total_l2p_ops > 0 {
            let total_us = bucket_elapsed.as_micros().min(u128::from(u64::MAX)) as u64;
            let put_us = total_us.saturating_mul(l2p_put_count) / total_l2p_ops;
            let delete_us = total_us.saturating_mul(l2p_delete_count) / total_l2p_ops;
            let remap_us = total_us.saturating_mul(l2p_remap_count) / total_l2p_ops;
            let range_us = total_us
                .saturating_sub(put_us)
                .saturating_sub(delete_us)
                .saturating_sub(remap_us);
            metrics.record_apply_l2p_put_batch(
                l2p_put_count,
                std::time::Duration::from_micros(put_us),
            );
            metrics.record_apply_l2p_delete_batch(
                l2p_delete_count,
                std::time::Duration::from_micros(delete_us),
            );
            metrics.record_apply_l2p_remap_batch(
                l2p_remap_count,
                std::time::Duration::from_micros(remap_us),
            );
            metrics.record_apply_l2p_remap_range_lane_work(
                l2p_remap_range_lba_count,
                std::time::Duration::from_micros(range_us),
            );
        }
        Ok(L2pBucketApplyResult {
            outcomes,
            rc_actions,
        })
    }

    /// B2 buffer variant of [`Self::apply_l2p_bucket`]. Same lane / per-shard
    /// dispatch contract, but writes land in `shard.l2p_buffer` instead of
    /// the paged tree. We don't hold `tree.write()` here: the buffer's own
    /// `Mutex<HashMap>` serialises concurrent inserts on this shard, and the
    /// background compactor is the only writer to the tree. RC bookkeeping
    /// is identical to the tree path — staged at commit time so that
    /// snapshot semantics and per-shard refcount apply lanes behave
    /// unchanged.
    /// B2 buffer variant of `apply_l2p_bucket`. Same caller contract:
    /// takes ownership of the bucket's entries; each `RangeSlice`
    /// entry contributes a partial `ApplyOutcome::L2pRemapRange` to be
    /// merged in `apply_ops_laned`.
    fn apply_l2p_bucket_buffer(
        volume: Arc<Volume>,
        sid: usize,
        indices: Vec<L2pBucketEntry>,
        lsn: Lsn,
        ops: &[WalOp],
        refcount_shards: &[Arc<crate::refcount::RcShard>],
        metrics: &MetaMetrics,
    ) -> Result<L2pBucketApplyResult> {
        use super::l2p_buffer::BufferLookup;
        let shard = &volume.shards[sid];
        let mut outcomes = Vec::with_capacity(indices.len());
        let mut rc_actions = Vec::new();
        // Snapshot the current published read view once. Lookups for `cur`
        // fall through to this view on buffer miss. Compactor publishes a
        // new view on each cycle; capturing once per-bucket is safe because
        // any committed-but-uncompacted state we'd miss in this view still
        // shows up in `shard.l2p_buffer.lookup`.
        let read_view_prepare_started = std::time::Instant::now();
        let read_view: Arc<crate::paged::ReadView> = shard.read_view.read().clone();
        let read_view_prepare = read_view_prepare_started.elapsed();
        let mut l2p_put_count = 0u64;
        let mut l2p_delete_count = 0u64;
        let mut l2p_remap_count = 0u64;
        let mut l2p_remap_range_lba_count = 0u64;
        let bucket_started = std::time::Instant::now();
        let ops_started = std::time::Instant::now();
        let ops_result = (|| -> Result<()> {
            for entry in &indices {
                if let L2pBucketEntry::RangeSlice { op_idx, lba_offsets } = entry {
                    let (range_start_lba, range_values) = match &ops[*op_idx] {
                        WalOp::L2pRemapRange {
                            start_lba, values, ..
                        } => (*start_lba, values.as_ref()),
                        other => unreachable!(
                            "RangeSlice op_idx points to non-range op: {other:?}"
                        ),
                    };
                    let n = range_values.len();
                    let mut applied_bits = vec![false; n].into_boxed_slice();
                    let mut prevs_box: Vec<Option<L2pValue>> = vec![None; n];

                    for &off in lba_offsets.iter() {
                        let lba = range_start_lba + off as u64;
                        let new_value = range_values[off as usize];
                        let cur = match shard.l2p_buffer.lookup(lba) {
                            BufferLookup::Present(v) => Some(v),
                            BufferLookup::Tombstone => None,
                            BufferLookup::Absent => read_view.get(lba)?,
                        };
                        if super::apply::seq_guard_rejects(new_value.seq(), cur.as_ref()) {
                            l2p_remap_range_lba_count += 1;
                            prevs_box[off as usize] = cur;
                            continue;
                        }
                        shard.l2p_buffer.insert(lba, new_value, lsn);
                        super::apply::record_dead(&volume, cur, lsn);
                        l2p_remap_range_lba_count += 1;
                        applied_bits[off as usize] = true;
                        prevs_box[off as usize] = cur;
                    }

                    outcomes.push((
                        *op_idx,
                        ApplyOutcome::L2pRemapRange {
                            applied: applied_bits,
                            prevs: prevs_box.into_boxed_slice(),
                            freed_pbas: Vec::new(),
                        },
                    ));
                    continue;
                }
                let idx = match entry {
                    L2pBucketEntry::Single(i) => *i,
                    L2pBucketEntry::RangeSlice { .. } => unreachable!("handled above"),
                };
                let outcome = match &ops[idx] {
                    WalOp::L2pPut { lba, value, .. } => {
                        let cur = match shard.l2p_buffer.lookup(*lba) {
                            BufferLookup::Present(v) => Some(v),
                            BufferLookup::Tombstone => None,
                            BufferLookup::Absent => read_view.get(*lba)?,
                        };
                        if super::apply::seq_guard_rejects(value.seq(), cur.as_ref()) {
                            l2p_put_count += 1;
                            outcomes.push((idx, ApplyOutcome::L2pPrev(cur)));
                            continue;
                        }
                        shard.l2p_buffer.insert(*lba, *value, lsn);
                        super::apply::record_dead(&volume, cur, lsn);
                        l2p_put_count += 1;
                        ApplyOutcome::L2pPrev(cur)
                    }
                    WalOp::L2pDelete { lba, .. } => {
                        let cur = match shard.l2p_buffer.lookup(*lba) {
                            BufferLookup::Present(v) => Some(v),
                            BufferLookup::Tombstone => None,
                            BufferLookup::Absent => read_view.get(*lba)?,
                        };
                        shard.l2p_buffer.insert_tombstone(*lba, lsn);
                        l2p_delete_count += 1;
                        ApplyOutcome::L2pPrev(cur)
                    }
                    WalOp::L2pRemap {
                        lba,
                        new_value,
                        guard,
                        ..
                    } => {
                        // RC-guarded remap: verify target pba refcount
                        // before mutating. Same lock-order rule as the
                        // tree-mode bucket (rc shard lookup only — buffer
                        // mutation needs no L2P lock).
                        if let Some((gp, min_rc)) = guard {
                            let gp_sid =
                                (xxh3_64(&gp.to_be_bytes()) as usize) % refcount_shards.len();
                            let cur_rc = refcount_shards[gp_sid].get(*gp)?;
                            if cur_rc < *min_rc {
                                l2p_remap_count += 1;
                                outcomes.push((
                                    idx,
                                    ApplyOutcome::L2pRemap {
                                        applied: false,
                                        prev: None,
                                        freed_pba: None,
                                    },
                                ));
                                continue;
                            }
                        }
                        let cur = match shard.l2p_buffer.lookup(*lba) {
                            BufferLookup::Present(v) => Some(v),
                            BufferLookup::Tombstone => None,
                            BufferLookup::Absent => read_view.get(*lba)?,
                        };
                        if super::apply::seq_guard_rejects(new_value.seq(), cur.as_ref()) {
                            l2p_remap_count += 1;
                            outcomes.push((
                                idx,
                                ApplyOutcome::L2pRemap {
                                    applied: false,
                                    prev: cur,
                                    freed_pba: None,
                                },
                            ));
                            continue;
                        }
                        shard.l2p_buffer.insert(*lba, *new_value, lsn);
                        super::apply::record_dead(&volume, cur, lsn);
                        l2p_remap_count += 1;
                        ApplyOutcome::L2pRemap {
                            applied: true,
                            prev: cur,
                            freed_pba: None,
                        }
                    }
                    other => unreachable!("L2P bucket holds only L2P ops; saw {other:?}"),
                };
                outcomes.push((idx, outcome));
            }
            Ok(())
        })();
        let ops_elapsed = ops_started.elapsed();
        ops_result?;
        let bucket_elapsed = bucket_started.elapsed();
        let total_l2p_ops =
            l2p_put_count + l2p_delete_count + l2p_remap_count + l2p_remap_range_lba_count;
        metrics.record_apply_l2p_bucket_stages(
            total_l2p_ops,
            bucket_elapsed,
            std::time::Duration::ZERO,
            read_view_prepare,
            ops_elapsed,
            std::time::Duration::ZERO,
            std::time::Duration::ZERO,
        );
        if bucket_elapsed.as_micros() >= 100_000 || ops_elapsed.as_micros() >= 100_000 {
            tracing::warn!(
                vol_ord = volume.ord,
                shard = sid,
                lsn,
                indices = total_l2p_ops,
                put = l2p_put_count,
                delete = l2p_delete_count,
                remap = l2p_remap_count,
                range_lbas = l2p_remap_range_lba_count,
                total_us = duration_us(bucket_elapsed),
                ops_us = duration_us(ops_elapsed),
                "metadb: slow l2p apply bucket (buffer)"
            );
        }
        if total_l2p_ops > 0 {
            let total_us = bucket_elapsed.as_micros().min(u128::from(u64::MAX)) as u64;
            let put_us = total_us.saturating_mul(l2p_put_count) / total_l2p_ops;
            let delete_us = total_us.saturating_mul(l2p_delete_count) / total_l2p_ops;
            let remap_us = total_us.saturating_mul(l2p_remap_count) / total_l2p_ops;
            let range_us = total_us
                .saturating_sub(put_us)
                .saturating_sub(delete_us)
                .saturating_sub(remap_us);
            metrics.record_apply_l2p_put_batch(
                l2p_put_count,
                std::time::Duration::from_micros(put_us),
            );
            metrics.record_apply_l2p_delete_batch(
                l2p_delete_count,
                std::time::Duration::from_micros(delete_us),
            );
            metrics.record_apply_l2p_remap_batch(
                l2p_remap_count,
                std::time::Duration::from_micros(remap_us),
            );
            metrics.record_apply_l2p_remap_range_lane_work(
                l2p_remap_range_lba_count,
                std::time::Duration::from_micros(range_us),
            );
        }
        Ok(L2pBucketApplyResult {
            outcomes,
            rc_actions,
        })
    }

    fn apply_refcount_bucket_to_tree(
        rc: Arc<crate::refcount::RcShard>,
        metrics: Arc<MetaMetrics>,
        mut actions: Vec<RcApplyAction>,
        lsn: Lsn,
    ) -> Result<RcBucketApplyResult> {
        let mut result = RcBucketApplyResult::default();
        if actions.is_empty() {
            return Ok(result);
        }
        actions.sort_by_key(|action| action.op_idx);
        let mut by_pba: HashMap<Pba, Vec<RcApplyAction>> = HashMap::new();
        for action in actions {
            by_pba.entry(action.pba).or_default().push(action);
        }
        let mut by_pba: Vec<_> = by_pba.into_iter().collect();
        by_pba.sort_by_key(|(pba, _)| *pba);

        for (pba, group) in by_pba {
            let can_coalesce_remap = group.iter().all(|action| !action.standalone_refcount)
                && (group.iter().all(|action| action.delta > 0)
                    || group.iter().all(|action| action.delta < 0));

            if can_coalesce_remap {
                let delta: i64 = group.iter().map(|action| action.delta).sum();
                let op_started = std::time::Instant::now();
                let op_idxs: Vec<usize> = group.iter().map(|a| a.op_idx).collect();
                // P0 diagnostic: trace every coalesced stage call so we can
                // confirm whether the +N at lsn=X actually reached the rc
                // shard. Filter via
                // `RUST_LOG=onyx_metadb::db::commit::rc_stage=trace`.
                tracing::trace!(
                    target: "onyx_metadb::db::commit::rc_stage",
                    pba,
                    coalesced_delta = delta,
                    ?op_idxs,
                    lsn,
                    "apply_refcount_bucket_to_tree: coalesced stage entry"
                );
                let (pre, new) = match rc.stage(pba, delta, lsn) {
                    Ok(r) => r,
                    Err(err) => {
                        tracing::error!(
                            target: "onyx_metadb::db::commit::rc_apply_underflow",
                            pba,
                            coalesced_delta = delta,
                            group_size = group.len(),
                            ?op_idxs,
                            lsn,
                            error = %err,
                            "apply_refcount_bucket_to_tree: coalesced group failed"
                        );
                        return Err(err);
                    }
                };
                tracing::trace!(
                    target: "onyx_metadb::db::commit::rc_stage",
                    pba,
                    coalesced_delta = delta,
                    pre,
                    new,
                    lsn,
                    "apply_refcount_bucket_to_tree: coalesced stage ok"
                );
                metrics.record_apply_refcount(op_started.elapsed());
                if new == 0 && pre > 0 {
                    if let Some(action) = group
                        .iter()
                        .rev()
                        .find(|action| action.remap_freed_candidate)
                    {
                        result
                            .remap_freed
                            .push((action.op_idx, action.pba, action.range_op));
                    }
                }
                continue;
            }

            for action in group {
                let op_started = std::time::Instant::now();
                let (pre, new) = match rc.stage(action.pba, action.delta, lsn) {
                    Ok(r) => r,
                    Err(err) => {
                        tracing::error!(
                            target: "onyx_metadb::db::commit::rc_apply_underflow",
                            pba = action.pba,
                            delta = action.delta,
                            op_idx = action.op_idx,
                            standalone = action.standalone_refcount,
                            remap_freed_candidate = action.remap_freed_candidate,
                            lsn,
                            error = %err,
                            "apply_refcount_bucket_to_tree: serial action failed"
                        );
                        return Err(err);
                    }
                };
                metrics.record_apply_refcount(op_started.elapsed());
                if action.remap_freed_candidate {
                    if new == 0 && pre > 0 {
                        result
                            .remap_freed
                            .push((action.op_idx, action.pba, action.range_op));
                    }
                } else if action.standalone_refcount {
                    result.refcount_outcomes.push((action.op_idx, new));
                }
            }
        }
        Ok(result)
    }

    fn apply_dedup_indices_to(
        dedup_index: &crate::dedup::DedupIndex,
        refcount_shards: &[Arc<crate::refcount::RcShard>],
        metrics: &MetaMetrics,
        ops: &[WalOp],
        indices: Vec<usize>,
        lsn: Lsn,
    ) -> Result<Vec<(usize, ApplyOutcome)>> {
        let batch_started = std::time::Instant::now();
        let mut outcomes = Vec::with_capacity(indices.len());
        let mut pending_puts: Vec<(Hash8, DedupValue, Option<Pba>, usize)> = Vec::new();
        // Phase 5: dedup-table mutations drive the global PBA refcount
        // (shared-page bookkeeping). The hot path no longer stages rc
        // deltas on L2P remaps, so any rc movement for a shared pba has
        // to ride along with the DedupPut/Delete/Compare* that gained
        // or lost the reference. Helpers below stay close to
        // `apply_dedup_put_with_rc` / `apply_dedup_delete_with_rc` in
        // `apply.rs` and use the same routing math (xxh3 mod shards)
        // because this lane bucket holds `Arc<RcShard>` directly, not
        // the outer `Shard` wrapper that `shard_for_key` expects.
        let rc_shard_for = |pba: Pba| -> usize {
            (xxh3_64(&pba.to_be_bytes()) as usize) % refcount_shards.len()
        };
        let stage_rc = |pba: Pba, delta: i64| -> Result<()> {
            let sid = rc_shard_for(pba);
            refcount_shards[sid].stage(pba, delta, lsn)?;
            Ok(())
        };
        // Phase 5 stale-entry tolerance: a dedup_index row can point to
        // a PBA whose rc has been driven to 0 by lineage GC without
        // cleanup removing the row. The matching put/delete must then
        // skip the decref instead of underflowing the rc table — see
        // `apply_dedup_put_with_rc` for the full rationale. We pre-read
        // the current rc once per stale candidate; within this lane the
        // LSN-ordered apply gate prevents concurrent rc mutation on the
        // same pba, so the floor check is sound.
        let stage_rc_decref_if_live = |pba: Pba| -> Result<()> {
            let sid = rc_shard_for(pba);
            if refcount_shards[sid].get(pba)? > 0 {
                refcount_shards[sid].stage(pba, -1, lsn)?;
            }
            Ok(())
        };
        // [[no-refcount-hot-path-design]] Phase 5 (WAL schema 0xB8):
        // every dedup put / delete carries an embedded `old_pba`
        // captured at `Transaction::commit` time. The live apply path
        // here uses it directly so that replay and live apply produce
        // the same rc deltas — apply is deterministic from the WAL
        // alone, which is required because the on-disk dedup_index
        // data pages are written eagerly per op (only the meta page
        // is checkpoint-gated). Reading dedup_index here would also
        // work for the live path, but using the embedded value keeps
        // the live and replay paths bit-identical and saves a
        // cuckoo lookup per op.
        let flush_pending_puts = |pending_puts: &mut Vec<(Hash8, DedupValue, Option<Pba>, usize)>,
                                  outcomes: &mut Vec<(usize, ApplyOutcome)>|
         -> Result<()> {
            if pending_puts.is_empty() {
                return Ok(());
            }
            let entries: Vec<(Hash8, DedupValue)> = pending_puts
                .iter()
                .map(|(hash, value, _, _)| (*hash, *value))
                .collect();
            let mut put_timings = DedupPutStageTimings::default();
            let started = std::time::Instant::now();
            dedup_index.put_many_with_metrics(&entries, lsn, &mut put_timings)?;
            metrics.record_dedup_forward_put_batch(pending_puts.len() as u64, started.elapsed());
            metrics.record_dedup_put_stages(put_timings);
            for (_, value, old_pba, idx) in pending_puts.drain(..) {
                let new_pba = value.head_pba();
                if old_pba != Some(new_pba) {
                    if let Some(op) = old_pba {
                        stage_rc_decref_if_live(op)?;
                    }
                    stage_rc(new_pba, 1)?;
                }
                outcomes.push((idx, ApplyOutcome::Dedup));
            }
            Ok(())
        };

        for idx in indices {
            match &ops[idx] {
                WalOp::DedupPut {
                    hash,
                    value,
                    old_pba,
                } => {
                    pending_puts.push((*hash, *value, *old_pba, idx));
                }
                WalOp::DedupPutGuarded {
                    hash,
                    value,
                    pba_guard,
                    min_rc,
                    old_pba,
                } => {
                    flush_pending_puts(&mut pending_puts, &mut outcomes)?;
                    let guard_started = std::time::Instant::now();
                    let rc = refcount_shards
                        .get(rc_shard_for(*pba_guard))
                        .ok_or_else(|| MetaDbError::Corruption("missing refcount shard".into()))?
                        .get(*pba_guard)?;
                    metrics.record_dedup_guard(guard_started.elapsed());
                    if rc >= *min_rc {
                        let mut put_timings = DedupPutStageTimings::default();
                        let started = std::time::Instant::now();
                        dedup_index.put_with_metrics(*hash, *value, lsn, &mut put_timings)?;
                        metrics.record_dedup_forward_put(started.elapsed());
                        metrics.record_dedup_put_stages(put_timings);
                        let new_pba = value.head_pba();
                        if *old_pba != Some(new_pba) {
                            if let Some(op) = *old_pba {
                                stage_rc_decref_if_live(op)?;
                            }
                            stage_rc(new_pba, 1)?;
                        }
                    }
                    outcomes.push((idx, ApplyOutcome::Dedup));
                }
                WalOp::DedupDelete { hash, old_pba } => {
                    flush_pending_puts(&mut pending_puts, &mut outcomes)?;
                    let started = std::time::Instant::now();
                    dedup_index.delete(hash, lsn)?;
                    metrics.record_dedup_forward_delete(started.elapsed());
                    if let Some(op) = *old_pba {
                        stage_rc_decref_if_live(op)?;
                    }
                    outcomes.push((idx, ApplyOutcome::Dedup));
                }
                WalOp::DedupCompareDelete { hash, old_value } => {
                    flush_pending_puts(&mut pending_puts, &mut outcomes)?;
                    let started = std::time::Instant::now();
                    let cur = dedup_index.get(hash)?;
                    let applied = cur.as_ref() == Some(old_value);
                    if applied {
                        dedup_index.delete(hash, lsn)?;
                        metrics.record_dedup_forward_delete(started.elapsed());
                        stage_rc_decref_if_live(old_value.head_pba())?;
                    }
                    outcomes.push((idx, ApplyOutcome::DedupCompare { applied }));
                }
                WalOp::DedupComparePut {
                    hash,
                    old_value,
                    new_value,
                } => {
                    flush_pending_puts(&mut pending_puts, &mut outcomes)?;
                    let started = std::time::Instant::now();
                    let cur = dedup_index.get(hash)?;
                    let applied = cur.as_ref() == Some(old_value);
                    if applied {
                        let mut put_timings = DedupPutStageTimings::default();
                        dedup_index.put_with_metrics(*hash, *new_value, lsn, &mut put_timings)?;
                        metrics.record_dedup_forward_put(started.elapsed());
                        metrics.record_dedup_put_stages(put_timings);
                        let old_pba = old_value.head_pba();
                        let new_pba = new_value.head_pba();
                        if old_pba != new_pba {
                            stage_rc_decref_if_live(old_pba)?;
                            stage_rc(new_pba, 1)?;
                        }
                    }
                    outcomes.push((idx, ApplyOutcome::DedupCompare { applied }));
                }
                other => unreachable!("dedup bucket holds only dedup ops; saw {other:?}"),
            };
        }
        flush_pending_puts(&mut pending_puts, &mut outcomes)?;
        metrics.record_apply_dedup_batch(outcomes.len() as u64, batch_started.elapsed());
        Ok(outcomes)
    }

    fn apply_ops_laned(
        &self,
        lsn: Lsn,
        op_count: usize,
        mut plan: QueuedLanePlan,
    ) -> Result<(Vec<ApplyOutcome>, LanedApplyTiming)> {
        let mut timing = LanedApplyTiming::default();
        let mut outcomes: Vec<Option<ApplyOutcome>> = (0..op_count).map(|_| None).collect();
        let mut first_error = None;

        let l2p_wait_started = std::time::Instant::now();
        for rx in plan.l2p_receivers.drain(..) {
            match rx.recv() {
                Ok(Ok(result)) => {
                    for (idx, outcome) in result.outcomes {
                        merge_l2p_outcome(&mut outcomes, idx, outcome);
                    }
                    for action in result.rc_actions {
                        let sid = shard_for_key(&self.refcount_shards, action.pba);
                        plan.rc_buckets[sid].push(action);
                    }
                }
                Ok(Err(err)) => {
                    if first_error.is_none() {
                        first_error = Some(err);
                    }
                }
                Err(_) => {
                    if first_error.is_none() {
                        first_error = Some(MetaDbError::Corruption(
                            "persistent L2P lane worker failed to return a result".into(),
                        ));
                    }
                }
            }
        }
        timing.l2p_wait = l2p_wait_started.elapsed();
        if let Some(err) = first_error {
            return Err(err);
        }

        let mut rc_receivers = Vec::new();
        let rc_enqueue_started = std::time::Instant::now();
        for sid in 0..plan.rc_buckets.len() {
            let actions = std::mem::take(&mut plan.rc_buckets[sid]);
            if actions.is_empty() {
                continue;
            }
            let rc = self.refcount_shards[sid].rc.clone();
            let metrics = self.metrics.clone();
            let (tx, rx) = crossbeam_channel::bounded(1);
            self.refcount_shards[sid].apply_lane.enqueue_ready(
                lsn,
                Box::new(move || {
                    let result = Self::apply_refcount_bucket_to_tree(rc, metrics, actions, lsn);
                    let _ = tx.send(result);
                }),
            );
            rc_receivers.push(rx);
        }
        timing.rc_enqueue = rc_enqueue_started.elapsed();
        self.complete_retained_dispatch(lsn);

        let mut first_error = None;
        let rc_wait_started = std::time::Instant::now();
        for rx in rc_receivers {
            match rx.recv() {
                Ok(Ok(result)) => {
                    for (idx, new) in result.refcount_outcomes {
                        outcomes[idx] = Some(ApplyOutcome::RefcountNew(new));
                    }
                    for (idx, pba, range_op) in result.remap_freed {
                        match (outcomes[idx].as_mut(), range_op) {
                            (Some(ApplyOutcome::L2pRemap { freed_pba, .. }), false) => {
                                *freed_pba = Some(pba);
                            }
                            (Some(ApplyOutcome::L2pRemapRange { freed_pbas, .. }), true) => {
                                freed_pbas.push(pba);
                            }
                            (other, range_op) => {
                                unreachable!(
                                    "remap rc action missing matching outcome: range_op={range_op} \
                                     outcome={other:?}"
                                )
                            }
                        }
                    }
                }
                Ok(Err(err)) => {
                    if first_error.is_none() {
                        first_error = Some(err);
                    }
                }
                Err(_) => {
                    if first_error.is_none() {
                        first_error = Some(MetaDbError::Corruption(
                            "persistent refcount lane worker failed to return a result".into(),
                        ));
                    }
                }
            }
        }
        timing.rc_wait = rc_wait_started.elapsed();
        if let Some(err) = first_error {
            return Err(err);
        }

        // Fan dedup work out across shards. Each non-empty bucket
        // gets its own apply closure on its shard's lane.
        //
        // The async path is valid only when:
        // 1. The commit carries a non-dedup op (L2P / refcount /
        //    volume lifecycle) whose outcome the caller is already
        //    blocked on. Pure-dedup commits — `db.put_dedup` /
        //    `db.delete_dedup` / `tx` with only dedup ops — must
        //    synchronise so the caller's follow-up `get_dedup`
        //    observes the put.
        // 2. No `DedupCompare*` ops are present — their `applied`
        //    flag is consumed by the caller (e.g. cleanup CAS path).
        //
        // When async-safe, hot-path callers only inspect `L2pRemap` /
        // `RefcountNew` outcome slots earlier in the vec; the
        // `ApplyOutcome::Dedup` marker for the async dedup ops is a
        // placeholder so the slot is filled.
        let has_non_dedup_op = plan.ops.iter().any(|op| {
            !matches!(
                op,
                WalOp::DedupPut { .. }
                    | WalOp::DedupPutGuarded { .. }
                    | WalOp::DedupDelete { .. }
                    | WalOp::DedupCompareDelete { .. }
                    | WalOp::DedupComparePut { .. }
            )
        });
        let no_sync_required_dedup_ops = plan.ops.iter().all(|op| {
            !matches!(
                op,
                WalOp::DedupCompareDelete { .. } | WalOp::DedupComparePut { .. }
            )
        });
        let dedup_async_safe = has_non_dedup_op && no_sync_required_dedup_ops;

        let mut dedup_receivers: Vec<
            crossbeam_channel::Receiver<Result<Vec<(usize, ApplyOutcome)>>>,
        > = Vec::new();
        let dedup_enqueue_started = std::time::Instant::now();
        let dedup_buckets = std::mem::take(&mut plan.dedup_buckets);
        let pendings = std::mem::take(&mut plan.dedup_pendings);
        let refcount_shards_arc: Arc<Vec<Arc<crate::refcount::RcShard>>> =
            Arc::new(self.refcount_shards.iter().map(|s| s.rc.clone()).collect());
        for (_sid, (pending_opt, bucket)) in pendings.into_iter().zip(dedup_buckets).enumerate() {
            let Some(pending) = pending_opt else { continue };
            let ready_at = std::time::Instant::now();
            let bucket_ops = bucket.len() as u64;
            let ops = plan.ops.clone();
            let dedup_index = self.dedup_index.clone();
            let refcount_shards_arc = refcount_shards_arc.clone();
            let metrics = self.metrics.clone();
            if dedup_async_safe {
                pending.set(Box::new(move || {
                    let ready_queue_wait = ready_at.elapsed();
                    let exec_started = std::time::Instant::now();
                    let _outcomes = Self::apply_dedup_indices_to(
                        dedup_index.as_ref(),
                        refcount_shards_arc.as_slice(),
                        metrics.as_ref(),
                        ops.as_slice(),
                        bucket,
                        lsn,
                    );
                    metrics.record_dedup_lane_task(
                        bucket_ops,
                        ready_queue_wait,
                        exec_started.elapsed(),
                    );
                }));
            } else {
                let (tx, rx) = crossbeam_channel::bounded(1);
                pending.set(Box::new(move || {
                    let ready_queue_wait = ready_at.elapsed();
                    let exec_started = std::time::Instant::now();
                    let outcomes = Self::apply_dedup_indices_to(
                        dedup_index.as_ref(),
                        refcount_shards_arc.as_slice(),
                        metrics.as_ref(),
                        ops.as_slice(),
                        bucket,
                        lsn,
                    );
                    metrics.record_dedup_lane_task(
                        bucket_ops,
                        ready_queue_wait,
                        exec_started.elapsed(),
                    );
                    let _ = tx.send(outcomes);
                }));
                dedup_receivers.push(rx);
            }
        }
        timing.dedup_enqueue = dedup_enqueue_started.elapsed();
        let dedup_wait_started = std::time::Instant::now();
        if dedup_async_safe {
            for (idx, op) in plan.ops.iter().enumerate() {
                if outcomes[idx].is_none()
                    && matches!(
                        op,
                        WalOp::DedupPut { .. }
                            | WalOp::DedupPutGuarded { .. }
                            | WalOp::DedupDelete { .. }
                    )
                {
                    outcomes[idx] = Some(ApplyOutcome::Dedup);
                }
            }
        } else {
            for rx in dedup_receivers {
                let dedup_outcomes = rx.recv().map_err(|_| {
                    MetaDbError::Corruption(
                        "persistent dedup lane worker failed to return a result".into(),
                    )
                })??;
                for (idx, outcome) in dedup_outcomes {
                    outcomes[idx] = Some(outcome);
                }
            }
        }
        timing.dedup_wait = dedup_wait_started.elapsed();

        Ok((
            outcomes
                .into_iter()
                .map(|o| o.expect("every op index filled by exactly one lane"))
                .collect(),
            timing,
        ))
    }

    pub(super) fn apply_replay_batch(
        volumes: &HashMap<VolumeOrdinal, Arc<Volume>>,
        refcount_shards: &[Shard],
        dedup_index: &Arc<crate::dedup::DedupIndex>,
        page_store: &Arc<PageStore>,
        metrics: &Arc<MetaMetrics>,
        lsn: Lsn,
        ops: &[WalOp],
        snap_info_for_vol: &dyn Fn(VolumeOrdinal) -> Vec<SnapInfo>,
    ) -> Result<Vec<ApplyOutcome>> {
        const BUCKET_THRESHOLD: usize = 8;
        if ops.len() < BUCKET_THRESHOLD
            || replay_batch_requires_serial_apply(ops, snap_info_for_vol)
        {
            let mut outcomes = Vec::with_capacity(ops.len());
            for op in ops {
                outcomes.push(apply_op_bare(
                    volumes,
                    refcount_shards,
                    dedup_index.as_ref(),
                    page_store,
                    lsn,
                    op,
                    snap_info_for_vol,
                )?);
            }
            return Ok(outcomes);
        }

        Self::apply_ops_grouped_to_lanes(
            volumes,
            refcount_shards,
            dedup_index,
            metrics,
            lsn,
            ops,
        )
    }

    fn apply_ops_grouped_to_lanes(
        volumes: &HashMap<VolumeOrdinal, Arc<Volume>>,
        refcount_shards: &[Shard],
        dedup_index: &Arc<crate::dedup::DedupIndex>,
        metrics: &Arc<MetaMetrics>,
        lsn: Lsn,
        ops: &[WalOp],
    ) -> Result<Vec<ApplyOutcome>> {
        let ops = Arc::new(ops.to_vec());
        let mut outcomes: Vec<Option<ApplyOutcome>> = (0..ops.len()).map(|_| None).collect();
        let mut l2p_buckets: HashMap<(VolumeOrdinal, usize), Vec<L2pBucketEntry>> = HashMap::new();
        let mut rc_buckets: Vec<Vec<RcApplyAction>> = vec![Vec::new(); refcount_shards.len()];
        let mut dedup_idxs: Vec<usize> = Vec::new();

        for (idx, op) in ops.iter().enumerate() {
            match op {
                WalOp::L2pPut { vol_ord, lba, .. }
                | WalOp::L2pDelete { vol_ord, lba }
                | WalOp::L2pRemap { vol_ord, lba, .. } => {
                    let volume = volumes.get(vol_ord).ok_or_else(|| {
                        MetaDbError::Corruption(format!("L2P op for unknown volume ord {vol_ord}"))
                    })?;
                    let sid = shard_for_key_l2p(&volume.shards, *lba);
                    l2p_buckets
                        .entry((*vol_ord, sid))
                        .or_default()
                        .push(L2pBucketEntry::Single(idx));
                }
                WalOp::L2pRemapRange {
                    vol_ord,
                    start_lba,
                    values,
                } => {
                    let volume = volumes.get(vol_ord).ok_or_else(|| {
                        MetaDbError::Corruption(format!(
                            "L2pRemapRange for unknown volume ord {vol_ord}"
                        ))
                    })?;
                    metrics.record_apply_l2p_remap_range_lane_ops(1);
                    let mut per_shard: HashMap<usize, Vec<u32>> = HashMap::new();
                    for off in 0..values.len() {
                        let lba = start_lba + off as u64;
                        let sid = shard_for_key_l2p(&volume.shards, lba);
                        per_shard.entry(sid).or_default().push(off as u32);
                    }
                    for (sid, offsets) in per_shard {
                        l2p_buckets
                            .entry((*vol_ord, sid))
                            .or_default()
                            .push(L2pBucketEntry::RangeSlice {
                                op_idx: idx,
                                lba_offsets: offsets.into_boxed_slice(),
                            });
                    }
                }
                WalOp::DedupPut { .. }
                | WalOp::DedupPutGuarded { .. }
                | WalOp::DedupDelete { .. }
                | WalOp::DedupCompareDelete { .. }
                | WalOp::DedupComparePut { .. } => {
                    dedup_idxs.push(idx);
                }
                WalOp::DropSnapshot { .. }
                | WalOp::CreateVolume { .. }
                | WalOp::DropVolume { .. }
                | WalOp::CloneVolume { .. }
                | WalOp::L2pRangeDelete { .. }
                | WalOp::FreePbas { .. }
                | WalOp::PromotionChunk { .. }
                | WalOp::PromotionComplete { .. } => {
                    unreachable!(
                        "lifecycle op must not reach apply_ops_grouped_to_lanes"
                    );
                }
            }
        }

        let refcount_shards_arc: Arc<Vec<Arc<crate::refcount::RcShard>>> = Arc::new(
            refcount_shards
                .iter()
                .map(|shard| shard.rc.clone())
                .collect(),
        );
        let mut l2p_sorted: Vec<_> = l2p_buckets.into_iter().collect();
        l2p_sorted.sort_by_key(|((vol, sid), _)| (*vol, *sid));

        let mut l2p_receivers = Vec::with_capacity(l2p_sorted.len());
        for ((vol_ord, sid), indices) in l2p_sorted {
            let volume = volumes
                .get(&vol_ord)
                .expect("volume presence checked during bucketing")
                .clone();
            let apply_volume = volume.clone();
            let apply_ops = ops.clone();
            let refcount_shards_arc = refcount_shards_arc.clone();
            let metrics = metrics.clone();
            let (tx, rx) = crossbeam_channel::bounded(1);
            volume.shards[sid].apply_lane.enqueue_ready(
                lsn,
                Box::new(move || {
                    let result = Self::apply_l2p_bucket(
                        apply_volume,
                        sid,
                        indices,
                        lsn,
                        apply_ops.as_slice(),
                        refcount_shards_arc.as_slice(),
                        metrics.as_ref(),
                    );
                    let _ = tx.send(result);
                }),
            );
            l2p_receivers.push(rx);
        }

        let mut first_error = None;
        for rx in l2p_receivers {
            match rx.recv() {
                Ok(Ok(result)) => {
                    for (idx, outcome) in result.outcomes {
                        merge_l2p_outcome(&mut outcomes, idx, outcome);
                    }
                    for action in result.rc_actions {
                        let sid = shard_for_key(refcount_shards, action.pba);
                        rc_buckets[sid].push(action);
                    }
                }
                Ok(Err(err)) => {
                    if first_error.is_none() {
                        first_error = Some(err);
                    }
                }
                Err(_) => {
                    if first_error.is_none() {
                        first_error = Some(MetaDbError::Corruption(
                            "replay L2P lane worker failed to return a result".into(),
                        ));
                    }
                }
            }
        }
        if let Some(err) = first_error {
            return Err(err);
        }

        let mut rc_receivers = Vec::new();
        for (sid, actions) in rc_buckets.into_iter().enumerate() {
            if actions.is_empty() {
                continue;
            }
            let rc = refcount_shards[sid].rc.clone();
            let metrics = metrics.clone();
            let (tx, rx) = crossbeam_channel::bounded(1);
            refcount_shards[sid].apply_lane.enqueue_ready(
                lsn,
                Box::new(move || {
                    let result = Self::apply_refcount_bucket_to_tree(rc, metrics, actions, lsn);
                    let _ = tx.send(result);
                }),
            );
            rc_receivers.push(rx);
        }

        let mut first_error = None;
        for rx in rc_receivers {
            match rx.recv() {
                Ok(Ok(result)) => {
                    for (idx, new) in result.refcount_outcomes {
                        outcomes[idx] = Some(ApplyOutcome::RefcountNew(new));
                    }
                    for (idx, pba, range_op) in result.remap_freed {
                        match (outcomes[idx].as_mut(), range_op) {
                            (Some(ApplyOutcome::L2pRemap { freed_pba, .. }), false) => {
                                *freed_pba = Some(pba);
                            }
                            (Some(ApplyOutcome::L2pRemapRange { freed_pbas, .. }), true) => {
                                freed_pbas.push(pba);
                            }
                            (other, range_op) => {
                                unreachable!(
                                    "remap rc action missing matching outcome: range_op={range_op} \
                                     outcome={other:?}"
                                )
                            }
                        }
                    }
                }
                Ok(Err(err)) => {
                    if first_error.is_none() {
                        first_error = Some(err);
                    }
                }
                Err(_) => {
                    if first_error.is_none() {
                        first_error = Some(MetaDbError::Corruption(
                            "replay refcount lane worker failed to return a result".into(),
                        ));
                    }
                }
            }
        }
        if let Some(err) = first_error {
            return Err(err);
        }

        for (idx, outcome) in Self::apply_dedup_indices_to(
            dedup_index.as_ref(),
            refcount_shards_arc.as_slice(),
            metrics.as_ref(),
            ops.as_slice(),
            dedup_idxs,
            lsn,
        )? {
            outcomes[idx] = Some(outcome);
        }

        Ok(outcomes
            .into_iter()
            .map(|o| o.expect("every op index filled by exactly one replay lane"))
            .collect())
    }

    fn apply_ops_grouped_to(
        volumes: &HashMap<VolumeOrdinal, Arc<Volume>>,
        refcount_shards: &[Shard],
        dedup_index: &Arc<crate::dedup::DedupIndex>,
        metrics: &Arc<MetaMetrics>,
        lsn: Lsn,
        ops: &[WalOp],
    ) -> Result<Vec<ApplyOutcome>> {
        let mut outcomes: Vec<Option<ApplyOutcome>> = (0..ops.len()).map(|_| None).collect();
        let mut l2p_buckets: HashMap<(VolumeOrdinal, usize), Vec<L2pBucketEntry>> = HashMap::new();
        let mut rc_buckets: Vec<Vec<RcApplyAction>> = vec![Vec::new(); refcount_shards.len()];
        let mut dedup_idxs: Vec<usize> = Vec::new();

        for (idx, op) in ops.iter().enumerate() {
            match op {
                WalOp::L2pPut { vol_ord, lba, .. }
                | WalOp::L2pDelete { vol_ord, lba }
                | WalOp::L2pRemap { vol_ord, lba, .. } => {
                    let volume = volumes.get(vol_ord).ok_or_else(|| {
                        MetaDbError::Corruption(format!("L2P op for unknown volume ord {vol_ord}"))
                    })?;
                    let sid = shard_for_key_l2p(&volume.shards, *lba);
                    l2p_buckets
                        .entry((*vol_ord, sid))
                        .or_default()
                        .push(L2pBucketEntry::Single(idx));
                }
                WalOp::L2pRemapRange {
                    vol_ord,
                    start_lba,
                    values,
                } => {
                    let volume = volumes.get(vol_ord).ok_or_else(|| {
                        MetaDbError::Corruption(format!(
                            "L2pRemapRange for unknown volume ord {vol_ord}"
                        ))
                    })?;
                    metrics.record_apply_l2p_remap_range_lane_ops(1);
                    let mut per_shard: HashMap<usize, Vec<u32>> = HashMap::new();
                    for off in 0..values.len() {
                        let lba = start_lba + off as u64;
                        let sid = shard_for_key_l2p(&volume.shards, lba);
                        per_shard.entry(sid).or_default().push(off as u32);
                    }
                    for (sid, offsets) in per_shard {
                        l2p_buckets
                            .entry((*vol_ord, sid))
                            .or_default()
                            .push(L2pBucketEntry::RangeSlice {
                                op_idx: idx,
                                lba_offsets: offsets.into_boxed_slice(),
                            });
                    }
                }
                WalOp::DedupPut { .. }
                | WalOp::DedupPutGuarded { .. }
                | WalOp::DedupDelete { .. }
                | WalOp::DedupCompareDelete { .. }
                | WalOp::DedupComparePut { .. } => {
                    dedup_idxs.push(idx);
                }
                WalOp::DropSnapshot { .. }
                | WalOp::CreateVolume { .. }
                | WalOp::DropVolume { .. }
                | WalOp::CloneVolume { .. }
                | WalOp::L2pRangeDelete { .. }
                | WalOp::FreePbas { .. }
                | WalOp::PromotionChunk { .. }
                | WalOp::PromotionComplete { .. } => {
                    unreachable!("lifecycle op must not reach apply_ops_grouped_to");
                }
            }
        }

        let refcount_shards_vec: Vec<Arc<crate::refcount::RcShard>> = refcount_shards
            .iter()
            .map(|shard| shard.rc.clone())
            .collect();
        let mut l2p_sorted: Vec<_> = l2p_buckets.into_iter().collect();
        l2p_sorted.sort_by_key(|((vol, sid), _)| (*vol, *sid));
        for ((vol_ord, sid), indices) in l2p_sorted {
            let volume = volumes
                .get(&vol_ord)
                .expect("volume presence checked during bucketing")
                .clone();
            let result = Self::apply_l2p_bucket(
                volume,
                sid,
                indices,
                lsn,
                ops,
                &refcount_shards_vec,
                metrics.as_ref(),
            )?;
            for (idx, outcome) in result.outcomes {
                merge_l2p_outcome(&mut outcomes, idx, outcome);
            }
            for action in result.rc_actions {
                let sid = shard_for_key(refcount_shards, action.pba);
                rc_buckets[sid].push(action);
            }
        }

        for (sid, actions) in rc_buckets.into_iter().enumerate() {
            if actions.is_empty() {
                continue;
            }
            let result = Self::apply_refcount_bucket_to_tree(
                refcount_shards[sid].rc.clone(),
                metrics.clone(),
                actions,
                lsn,
            )?;
            for (idx, new) in result.refcount_outcomes {
                outcomes[idx] = Some(ApplyOutcome::RefcountNew(new));
            }
            for (idx, pba, range_op) in result.remap_freed {
                match (outcomes[idx].as_mut(), range_op) {
                    (Some(ApplyOutcome::L2pRemap { freed_pba, .. }), false) => {
                        *freed_pba = Some(pba);
                    }
                    (Some(ApplyOutcome::L2pRemapRange { freed_pbas, .. }), true) => {
                        freed_pbas.push(pba);
                    }
                    (other, range_op) => {
                        unreachable!(
                            "remap rc action missing matching outcome: range_op={range_op} \
                             outcome={other:?}"
                        )
                    }
                }
            }
        }

        for (idx, outcome) in Self::apply_dedup_indices_to(
            dedup_index.as_ref(),
            refcount_shards_vec.as_slice(),
            metrics.as_ref(),
            ops,
            dedup_idxs,
            lsn,
        )? {
            outcomes[idx] = Some(outcome);
        }

        Ok(outcomes
            .into_iter()
            .map(|o| o.expect("every op index filled by exactly one bucket"))
            .collect())
    }

    /// Bucketed batch-apply. Only invoked for sufficiently large
    /// batches composed entirely of bucketable ops (plain L2P,
    /// unguarded/no-snapshot remap, refcount, dedup). See
    /// [`apply_commit_batch`] for the dispatch rule.
    fn apply_ops_grouped(
        &self,
        volumes: &HashMap<VolumeOrdinal, Arc<Volume>>,
        lsn: Lsn,
        ops: &[WalOp],
    ) -> Result<Vec<ApplyOutcome>> {
        Self::apply_ops_grouped_to(
            volumes,
            &self.refcount_shards,
            &self.dedup_index,
            &self.metrics,
            lsn,
            ops,
        )
    }
}

fn replay_batch_requires_serial_apply(
    ops: &[WalOp],
    snap_info_for_vol: &dyn Fn(VolumeOrdinal) -> Vec<SnapInfo>,
) -> bool {
    if batch_contains_lifecycle_op(ops) {
        return true;
    }

    let mut remap_vols = HashSet::new();
    for op in ops {
        match op {
            WalOp::L2pRemap { vol_ord, .. } | WalOp::L2pRemapRange { vol_ord, .. } => {
                remap_vols.insert(*vol_ord);
            }
            _ => {}
        }
    }
    remap_vols
        .into_iter()
        .any(|vol_ord| !snap_info_for_vol(vol_ord).is_empty())
}

/// Record per-op-type apply latency for the serial fallback path.
/// Lifecycle ops (DropSnapshot / CreateVolume / DropVolume / CloneVolume) are
/// rare and self-instrument elsewhere, so they're skipped here.
fn record_per_op_apply(metrics: &MetaMetrics, op: &WalOp, elapsed: std::time::Duration) {
    match op {
        WalOp::L2pPut { .. } => metrics.record_apply_l2p_put(elapsed),
        WalOp::L2pDelete { .. } => metrics.record_apply_l2p_delete(elapsed),
        WalOp::L2pRemap { .. } => metrics.record_apply_l2p_remap(elapsed),
        WalOp::L2pRangeDelete { .. } => metrics.record_apply_l2p_range_delete(elapsed),
        WalOp::L2pRemapRange { values, .. } => {
            metrics.record_apply_l2p_remap_range(values.len() as u64, elapsed)
        }
        WalOp::DedupPut { .. }
        | WalOp::DedupPutGuarded { .. }
        | WalOp::DedupDelete { .. }
        | WalOp::DedupCompareDelete { .. }
        | WalOp::DedupComparePut { .. } => metrics.record_apply_dedup(elapsed),
        WalOp::DropSnapshot { .. }
        | WalOp::CreateVolume { .. }
        | WalOp::DropVolume { .. }
        | WalOp::CloneVolume { .. }
        | WalOp::FreePbas { .. }
        | WalOp::PromotionChunk { .. }
        | WalOp::PromotionComplete { .. } => {}
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn footprint(lanes: impl IntoIterator<Item = DispatchLaneKey>) -> DispatchFootprint {
        DispatchFootprint {
            global: false,
            lanes: lanes.into_iter().collect(),
        }
    }

    fn entry(footprint: DispatchFootprint, durable: bool) -> DispatchEntry {
        DispatchEntry { footprint, durable }
    }

    #[test]
    fn dispatch_scheduler_allows_disjoint_higher_lsn_to_bypass() {
        let mut state = DispatchState::default();
        state
            .pending
            .insert(10, entry(footprint([DispatchLaneKey::L2p(0, 0)]), false));
        state
            .pending
            .insert(11, entry(footprint([DispatchLaneKey::L2p(0, 1)]), true));

        assert!(
            dispatch_ready(&state, 11),
            "lower undurable work on another shard must not block dispatch"
        );
    }

    #[test]
    fn dispatch_scheduler_blocks_conflicting_higher_lsn() {
        let mut state = DispatchState::default();
        state
            .pending
            .insert(10, entry(footprint([DispatchLaneKey::Refcount(2)]), false));
        state
            .pending
            .insert(11, entry(footprint([DispatchLaneKey::Refcount(2)]), true));

        assert!(
            !dispatch_ready(&state, 11),
            "same lane must preserve WAL LSN dispatch order"
        );
        state.pending.remove(&10);
        assert!(dispatch_ready(&state, 11));
    }

    #[test]
    fn dispatch_scheduler_treats_global_as_conflicting_with_every_lane() {
        let mut state = DispatchState::default();
        state
            .pending
            .insert(10, entry(DispatchFootprint::global(), true));
        state
            .pending
            .insert(11, entry(footprint([DispatchLaneKey::Dedup(0)]), true));

        assert!(
            !dispatch_ready(&state, 11),
            "global serial work must retain the old FIFO barrier"
        );
    }

    #[test]
    fn small_remap_batches_use_lane_dispatch_not_global_serial() {
        let dir = tempfile::TempDir::new().unwrap();
        let db = Db::create(dir.path()).unwrap();
        let mut raw = [0u8; crate::paged::format::LEAF_VALUE_SIZE];
        raw[..8].copy_from_slice(&123_u64.to_be_bytes());

        let ops = [WalOp::L2pRemap {
            vol_ord: BOOTSTRAP_VOLUME_ORD,
            lba: 7,
            new_value: L2pValue(raw),
            guard: None,
        }];

        assert!(
            !db.batch_uses_serial_apply(&ops),
            "tiny remap commits must keep precise L2P/refcount footprints so they do not block dedup dispatch globally"
        );
        let plan = db
            .build_lane_dispatch_plan(&db.volumes.read().clone(), &ops)
            .unwrap();
        let footprint = DispatchFootprint::from_lane_plan(&plan);
        assert!(!footprint.global);
        assert!(
            footprint
                .lanes
                .iter()
                .any(|lane| matches!(lane, DispatchLaneKey::L2p(BOOTSTRAP_VOLUME_ORD, _)))
        );
        assert!(
            !footprint
                .lanes
                .iter()
                .any(|lane| matches!(lane, DispatchLaneKey::Dedup(_))),
            "remap-only commits should not conflict with dedup shards"
        );
    }
}
